// ============= 유틸 =============
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// ============= 메인 =============
async function main() {
  // 환경변수 확인
  if (!process.env.GEMINI_API_KEY) {
    console.warn("⚠️  GEMINI_API_KEY 미설정 (Gemini 사용 불가)");
  }
  if (!process.env.OPENAI_API_KEY) {
