func main() {
    print("🚀 Benchmark Framework 테스트");
    print("================================");
    print("");

    // 테스트 설정
    let element_counts = [u32]{100, 1000, 10000};

    for count_idx = 0; count_idx < len(element_counts); count_idx = count_idx + 1 {
        let count = element_counts[count_idx];

        print("╔════════════════════════════════════════════╗");
        print("║ Test Set: " + count + " elements          ║");
        print("╚════════════════════════════════════════════╝");
        print("");

        // 테스트 1: 생성 벤치마크
        print("━━━ Creation Benchmark ━━━");
        let soa_create = benchmark.benchmark_soa_creation(count);
        let aos_create = benchmark.benchmark_aos_creation(count);

        benchmark.report_metric(soa_create);
        benchmark.report_metric(aos_create);
        benchmark.report_comparison(soa_create, aos_create);

        // 테스트 2: 점곱 벤치마크
        print("━━━ Dot Product Benchmark ━━━");
        let soa_dot = benchmark.benchmark_soa_dot_product(count);
        let aos_dot = benchmark.benchmark_aos_dot_product(count);

        benchmark.report_metric(soa_dot);
        benchmark.report_metric(aos_dot);
        benchmark.report_comparison(soa_dot, aos_dot);

        print("");
    }

    print("✨ Benchmark 테스트 완료!");
    print("");
    print("📈 요약:");
    print("   • SoA는 메모리 접근 패턴이 더 효율적");
    print("   • SIMD 병렬화에 최적화");
    print("   • 캐시 라인 활용 극대화");
    print("   • 대규모 데이터셋에서 3-6배 처리량 향상 예상");
    print("");
}

