                aos.data[j].z = f32(j) + 0.3;
            }
        }

        let elapsed = timer.timer_stop();
        let elapsed_micro = elapsed / NANO_PER_MICRO;
        let throughput = f32(iterations * u64(element_count)) / (f32(elapsed_micro) / 1_000_000.0);
        let latency = f32(elapsed_micro) / f32(iterations * u64(element_count));

        return PerformanceMetric {
            name: "AoS Creation",
            iterations: iterations,
            elapsed_time: elapsed_micro,
            throughput: throughput,
            latency: latency,
            memory_used: u64(element_count) * 12,
            cache_lines: (u64(element_count) * 12 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
            is_soa: false,
        };
    }

    // benchmark_aos_dot_product: AoS 점곱 벤치마크
    func benchmark_aos_dot_product(element_count: u32) -> PerformanceMetric {
        // 두 개의 AoS 벡터 생성
        let v1 = Vector3DAoS {
            data: make([Vector3D], element_count),
            count: element_count,
        };

        let v2 = Vector3DAoS {
            data: make([Vector3D], element_count),
            count: element_count,
        };

        // 데이터 초기화
        for j = 0; j < element_count; j = j + 1 {
            v1.data[j].x = 1.0;
            v1.data[j].y = 2.0;
            v1.data[j].z = 3.0;

            v2.data[j].x = 4.0;
            v2.data[j].y = 5.0;
            v2.data[j].z = 6.0;
        }

        let iterations = u64(1000);
        let timer = timer_start();

        for i = 0; i < iterations; i = i + 1 {
            // 점곱 계산
            for j = 0; j < element_count; j = j + 1 {
                let dot = v1.data[j].x * v2.data[j].x +
                          v1.data[j].y * v2.data[j].y +
                          v1.data[j].z * v2.data[j].z;
            }
        }

        let elapsed = timer.timer_stop();
        let elapsed_micro = elapsed / NANO_PER_MICRO;
        let total_ops = iterations * u64(element_count);
        let throughput = f32(total_ops) / (f32(elapsed_micro) / 1_000_000.0);
        let latency = f32(elapsed_micro) / f32(total_ops);

        return PerformanceMetric {
            name: "AoS Dot Product",
            iterations: iterations,
            elapsed_time: elapsed_micro,
            throughput: throughput,
            latency: latency,
            memory_used: u64(element_count) * 24,
            cache_lines: (u64(element_count) * 12 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
            is_soa: false,
        };
    }

    // ========================================================================
    // 벤치마크 분석
    // ========================================================================

    // calc_improvement: SoA vs AoS 성능 개선율 계산
    func calc_improvement(soa_metric: PerformanceMetric, aos_metric: PerformanceMetric) -> f32 {
        if aos_metric.throughput == 0.0 {
            return 0.0;
        }
        return (soa_metric.throughput - aos_metric.throughput) / aos_metric.throughput * 100.0;
    }

    // ========================================================================
    // 리포트 생성
    // ========================================================================

    // report_metric: 단일 메트릭 출력
    func report_metric(metric: PerformanceMetric) {
        let layout = if metric.is_soa { "SoA" } else { "AoS" };

        print("📊 " + metric.name + " (" + layout + ")");
        print("   Iterations:   " + metric.iterations);
        print("   Total Time:   " + metric.elapsed_time + " μs");
        print("   Throughput:   " + metric.throughput + " ops/sec");
        print("   Latency:      " + metric.latency + " μs/op");
        print("   Memory Used:  " + metric.memory_used + " bytes");
        print("   Cache Lines:  " + metric.cache_lines);
        print("");
    }

    // report_comparison: SoA vs AoS 비교 리포트
    func report_comparison(soa: PerformanceMetric, aos: PerformanceMetric) {
        let improvement = calc_improvement(soa, aos);
        let latency_improvement = (aos.latency - soa.latency) / aos.latency * 100.0;

        print("╔════════════════════════════════════════════╗");
        print("║ Performance Comparison: SoA vs AoS        ║");
        print("╚════════════════════════════════════════════╝");
        print("");

        print("Throughput:");
        print("  AoS: " + aos.throughput + " ops/sec");
        print("  SoA: " + soa.throughput + " ops/sec");
        print("  Improvement: " + improvement + "%");
        print("");

        print("Latency:");
        print("  AoS: " + aos.latency + " μs/op");
        print("  SoA: " + soa.latency + " μs/op");
        print("  Improvement: " + latency_improvement + "%");
        print("");

        print("Cache Efficiency:");
        print("  AoS: " + aos.cache_lines + " cache lines");
        print("  SoA: " + soa.cache_lines + " cache lines");
        let cache_reduction = f32(aos.cache_lines - soa.cache_lines) / f32(aos.cache_lines) * 100.0;
        print("  Reduction: " + cache_reduction + "%");
        print("");
    }
}

