    // compare_results: SoA와 AoS 결과 비교
    func compare_results(soa: BenchmarkResult, aos: BenchmarkResult) -> BenchmarkComparison {
        let improvement = (soa.throughput_ops_per_sec - aos.throughput_ops_per_sec) /
                         aos.throughput_ops_per_sec * 100.0;
        let speedup = soa.throughput_ops_per_sec / (aos.throughput_ops_per_sec + 0.001);

        return BenchmarkComparison {
            test_name: soa.benchmark_name,
            soa_result: soa,
            aos_result: aos,
            improvement_percent: improvement,
            speedup_factor: speedup,
        };
    }

    // ========================================================================
    // 리포팅
    // ========================================================================

    // report_result: 벤치마크 결과 출력
    func report_result(result: BenchmarkResult) {
        print("📊 " + result.benchmark_name + " (" + result.layout_type + ")");
        print("   Iterations: " + result.iterations);
        print("   Elements: " + result.total_elements);
        print("   Time: " + result.total_time_us + " μs");
        print("   Throughput: " + result.throughput_ops_per_sec + " ops/sec");
        print("   Latency: " + result.latency_us_per_op + " μs/op");
        print("   Memory: " + result.memory_bytes + " bytes");
        print("");
    }

    // report_comparison: 비교 리포트 출력
    func report_comparison(comp: BenchmarkComparison) {
        print("╔════════════════════════════════════════╗");
        print("║ Benchmark: " + comp.test_name + " (SoA vs AoS) ║");
        print("╚════════════════════════════════════════╝");
        print("");

        report_result(comp.soa_result);
        report_result(comp.aos_result);

        print("━━━ Comparison ━━━");
        print("Speedup: " + comp.speedup_factor + "x");
        print("Improvement: " + comp.improvement_percent + "%");
        print("");
    }
}

