            return (false, analysis);
        }

        // 조건 2: 버퍼 끝을 초과
        if final_offset > buffer_end {
            let analysis = PointerAnalysis {
                buffer_name: "buffer",
                base_offset: base_offset,
                operation: "overflow",
                is_safe: false,
                violation_reason: "Pointer overflow: " + final_offset + " > " + buffer_end,
            };
            return (false, analysis);
        }

        // 안전함
        let analysis = PointerAnalysis {
            buffer_name: "buffer",
            base_offset: base_offset,
            operation: "safe",
            is_safe: true,
            violation_reason: "",
        };
        return (true, analysis);
    }

    // check_slice_range: 슬라이스 범위 정적 검증
    // arr[start:end]가 범위 내인지 확인
    @inline
    func check_slice_range(
        start_idx: u64,
        end_idx: u64,
        array_size: u64
    ) -> (bool, BoundaryViolation) {
        // 조건 1: start <= end
        if start_idx > end_idx {
            let violation = BoundaryViolation {
                violation_type: VIOLATION_SLICE_RANGE,
                buffer_name: "array_slice",
                attempted_access: start_idx,
                buffer_start: 0,
                buffer_end: array_size,
                message: "Invalid slice: start (" + start_idx + ") > end (" + end_idx + ")",
            };
            return (false, violation);
        }

        // 조건 2: end <= array_size
        if end_idx > array_size {
            let violation = BoundaryViolation {
                violation_type: VIOLATION_SLICE_RANGE,
                buffer_name: "array_slice",
                attempted_access: end_idx,
                buffer_start: 0,
                buffer_end: array_size,
                message: "Slice end (" + end_idx + ") exceeds array size (" + array_size + ")",
            };
            return (false, violation);
        }

        let violation = BoundaryViolation {
            violation_type: 0,
            buffer_name: "array_slice",
            attempted_access: start_idx,
            buffer_start: 0,
            buffer_end: array_size,
            message: "OK",
        };
        return (true, violation);
    }

    // ========================================================================
    // 정적 분석기 (AST 기반)
    // ========================================================================

    struct StaticAnalyzer {
        buffers: [StaticBuffer];
        analyses: [PointerAnalysis];
        violations: [BoundaryViolation];
    }

    // analyzer_new: 새로운 분석기 생성
    func analyzer_new() -> StaticAnalyzer {
        return StaticAnalyzer {
            buffers: make([StaticBuffer], 0),
            analyses: make([PointerAnalysis], 0),
            violations: make([BoundaryViolation], 0),
        };
    }

    // analyzer_register_buffer: 버퍼 등록
    func (a: *StaticAnalyzer) analyzer_register_buffer(
        name: string,
        size: u64,
        element_count: u64,
        element_size: u64
    ) {
        let buffer = StaticBuffer {
            name: name,
            size: size,
            element_count: element_count,
            element_size: element_size,
            is_stack_allocated: false,
        };

        a.buffers.push(buffer);
    }

    // analyzer_check_array_access: 배열 접근 검사
    func (a: *StaticAnalyzer) analyzer_check_array_access(
        buffer_name: string,
        index: u64
    ) -> bool {
        // 해당 버퍼 찾기
        let buffer: StaticBuffer;
        let found = false;

        for i = 0; i < len(a.buffers); i = i + 1 {
            if a.buffers[i].name == buffer_name {
                buffer = a.buffers[i];
                found = true;
                break;
            }
        }

        if !found {
            print("ERROR: Buffer '" + buffer_name + "' not registered");
            return false;
        }

        // 경계 검증
        let (ok, violation) = check_array_access(buffer.element_count, index);

        if !ok {
            a.violations.push(violation);
        }

        return ok;
    }

    // analyzer_check_pointer_arithmetic: 포인터 연산 검사
    func (a: *StaticAnalyzer) analyzer_check_pointer_arithmetic(
        buffer_name: string,
        base_offset: i64,
        arithmetic_offset: i64
    ) -> bool {
        let buffer: StaticBuffer;
        let found = false;

        for i = 0; i < len(a.buffers); i = i + 1 {
            if a.buffers[i].name == buffer_name {
                buffer = a.buffers[i];
                found = true;
                break;
            }
        }

        if !found {
            print("ERROR: Buffer '" + buffer_name + "' not registered");
            return false;
        }

        // 포인터 연산 검증
        let (ok, analysis) = check_pointer_arithmetic(
            base_offset,
            arithmetic_offset,
            0,
            i64(buffer.size)
        );

        a.analyses.push(analysis);

        if !ok {
            let violation = BoundaryViolation {
                violation_type: if analysis.operation == "underflow" { 2 } else { 1 },
                buffer_name: buffer_name,
                attempted_access: u64(base_offset + arithmetic_offset),
                buffer_start: 0,
                buffer_end: buffer.size,
                message: analysis.violation_reason,
            };
            a.violations.push(violation);
        }

        return ok;
    }

    // analyzer_has_violations: 위반이 있는가?
    func (a: *StaticAnalyzer) analyzer_has_violations() -> bool {
        return len(a.violations) > 0;
    }

    // analyzer_report: 분석 리포트
    func (a: *StaticAnalyzer) analyzer_report() {
        print("╔════════════════════════════════════════╗");
        print("║ Static Boundary Analysis Report       ║");
        print("╚════════════════════════════════════════╝");
        print("");

        print("📋 Registered Buffers: " + len(a.buffers));
        for i = 0; i < len(a.buffers); i = i + 1 {
            let buf = a.buffers[i];
            print("   [" + i + "] " + buf.name + ": " + buf.element_count + " elements × " + buf.element_size + " bytes");
        }
        print("");

        print("🔍 Analysis Results: " + len(a.analyses) + " operations");
        for i = 0; i < len(a.analyses); i = i + 1 {
            let analysis = a.analyses[i];
            let status = if analysis.is_safe { "✅ SAFE" } else { "❌ UNSAFE" };
            print("   [" + i + "] " + status + ": " + analysis.buffer_name + " (" + analysis.operation + ")");
        }
        print("");

        if len(a.violations) > 0 {
            print("⚠️  VIOLATIONS FOUND: " + len(a.violations));
            for i = 0; i < len(a.violations); i = i + 1 {
                let violation = a.violations[i];
                print("   [Violation #" + (i + 1) + "]");
                print("   Type: " + violation.violation_type);
                print("   Buffer: " + violation.buffer_name);
                print("   Attempted: " + violation.attempted_access);
                print("   Valid Range: [" + violation.buffer_start + ", " + violation.buffer_end + "]");
                print("   Message: " + violation.message);
                print("");
            }
        } else {
            print("✅ NO VIOLATIONS - All pointer accesses are safe!");
        }

        print("");
    }

    // ========================================================================
    // 부정 테스트 (Negative Test)
    // ========================================================================

    // test_intentional_violations: 일부러 위반 주입
    func test_intentional_violations() -> bool {
        print("🧪 Negative Test: Intentional Boundary Violations");
        print("================================================");
        print("");

        let analyzer = analyzer_new();

        // 버퍼 등록 (100개 요소, 각 4바이트 float)
        analyzer.analyzer_register_buffer("vec3_array", 400, 100, 4);

        print("Registered buffer: vec3_array (100 elements)");
        print("");

        // 테스트 1: 정상 접근
        print("Test 1: Valid Access (index 50)");
        let ok1 = analyzer.analyzer_check_array_access("vec3_array", 50);
        print("   Result: " + if ok1 { "✅ PASS" } else { "❌ FAIL" });
        print("");

        // 테스트 2: 범위 초과
        print("Test 2: Out of Bounds (index 150)");
        let ok2 = analyzer.analyzer_check_array_access("vec3_array", 150);
        print("   Result: " + if ok2 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 3: 포인터 오버플로우
        print("Test 3: Pointer Overflow (base 0, offset +500)");
        let ok3 = analyzer.analyzer_check_pointer_arithmetic("vec3_array", 0, 500);
        print("   Result: " + if ok3 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 4: 포인터 언더플로우
        print("Test 4: Pointer Underflow (base 0, offset -100)");
        let ok4 = analyzer.analyzer_check_pointer_arithmetic("vec3_array", 0, -100);
        print("   Result: " + if ok4 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 테스트 5: 슬라이스 범위 위반
        print("Test 5: Invalid Slice (start 50, end 150)");
        let (ok5, _) = check_slice_range(50, 150, 100);
        print("   Result: " + if ok5 { "✅ PASS (not caught)" } else { "❌ FAIL (caught)" });
        print("");

        // 리포트
        analyzer.analyzer_report();

        // 결과: 적어도 3개 이상의 위반이 감지되어야 함
        let violation_count = len(analyzer.violations);
        print("📊 Summary: " + violation_count + " violations detected");
        print("   Expected: >= 3 violations");
        print("   Status: " + if violation_count >= 3 { "✅ PASS" } else { "❌ FAIL" });

        return violation_count >= 3;
    }
}

// ============================================================================
// 메인 테스트
// ============================================================================

func main() {
    print("");
    print("╔════════════════════════════════════════════════════════╗");
    print("║ Static Boundary Checker - Compile-Time Verification   ║");
    print("╚════════════════════════════════════════════════════════╝");
    print("");

    // 부정 테스트 실행
    let test_result = boundary_static.test_intentional_violations();

    print("");
    print("╔════════════════════════════════════════════════════════╗");
    if test_result {
        print("║ ✅ Negative Test PASSED - Violations Detected!        ║");
    } else {
        print("║ ❌ Negative Test FAILED - Some violations missed!     ║");
    }
    print("╚════════════════════════════════════════════════════════╝");
    print("");

    print("💡 Key Points:");
    print("   • Static analysis catches pointer violations at compile time");
    print("   • Zero runtime overhead - all checks performed before execution");
    print("   • Prevents buffer overflows and underflows");
    print("   • Essential for Zero-Copy safety guarantees");
    print("");
}

