        print(\"📊 L1 Data Cache Load Misses\");
        print(\"\");
        print(\"  SoA: \" + soa_l1_misses);
        print(\"  AoS: \" + aos_l1_misses);
        print(\"  Improvement: \" + u32(f32(aos_l1_misses - soa_l1_misses) / f32(aos_l1_misses) * 100.0) + \"% reduction\");
        print(\"\");

        // 그래프
        let max_val = aos_l1_misses;
        let soa_bar_len = u32(f32(soa_l1_misses) / f32(max_val) * 40.0);
        let aos_bar_len = u32(f32(aos_l1_misses) / f32(max_val) * 40.0);

        print(\"  SoA: \");
