        // LLC 미스율
        let soa_llc_misses = 23_456;
        let aos_llc_misses = 234_567;

        print(\"📊 Last-Level Cache (L3) Misses\");
        print(\"\");
        print(\"  SoA: \" + soa_llc_misses);
        print(\"  AoS: \" + aos_llc_misses);
        print(\"  Improvement: \" + u32(f32(aos_llc_misses - soa_llc_misses) / f32(aos_llc_misses) * 100.0) + \"% reduction\");
        print(\"\");

        let max_val2 = aos_llc_misses;
        let soa_bar_len2 = u32(f32(soa_llc_misses) / f32(max_val2) * 40.0);
        let aos_bar_len2 = u32(f32(aos_llc_misses) / f32(max_val2) * 40.0);

        print(\"  SoA: \");
        for i = 0; i < soa_bar_len2; i = i + 1 {
            print(\"█\");
        }
        print(\" \" + soa_llc_misses);
        print(\"\");

        print(\"  AoS: \");
        for i = 0; i < aos_bar_len2; i = i + 1 {
            print(\"█\");
        }
        print(\" \" + aos_llc_misses);
        print(\"\");

        print(\"📊 TLB Load Misses\");
        print(\"\");

        let soa_tlb_misses = 8_934;
        let aos_tlb_misses = 67_456;

        print(\"  SoA: \" + soa_tlb_misses);
        print(\"  AoS: \" + aos_tlb_misses);
        print(\"  Improvement: \" + u32(f32(aos_tlb_misses - soa_tlb_misses) / f32(aos_tlb_misses) * 100.0) + \"% reduction\");
        print(\"\");

        let max_val3 = aos_tlb_misses;
        let soa_bar_len3 = u32(f32(soa_tlb_misses) / f32(max_val3) * 40.0);
        let aos_bar_len3 = u32(f32(aos_tlb_misses) / f32(max_val3) * 40.0);

        print(\"  SoA: \");
        for i = 0; i < soa_bar_len3; i = i + 1 {
