   325→    // calc_improvement: SoA vs AoS 성능 개선율 계산
   326→    func calc_improvement(soa_metric: PerformanceMetric, aos_metric: PerformanceMetric) -> f32 {
   327→        if aos_metric.throughput == 0.0 {
