   361→        print("Throughput:");
   362→        print("  AoS: " + aos.throughput + " ops/sec");
   363→        print("  SoA: " + soa.throughput + " ops/sec");
   364→        print("  Improvement: " + improvement + "%");
   365→        print("");
   366→
   367→        print("Latency:");
