   436→    // 테스트 2: 락으로 보호된 접근
   437→    print("✅ 테스트 2: 락으로 보호된 접근");
   438→
   439→    let a3 = fvx.MemoryAccess {
   440→        thread_id: 1,
   441→        address: 2000,
   442→        operation: fvx.OP_WRITE,
   443→        timestamp: 0,
