   474→    // 테스트 4: 경쟁 상태 감지
   475→    print("✅ 테스트 4: 경쟁 상태 감지");
   476→
   477→    // Thread 1: 주소 5000에 쓰기 (락 없음)
   478→    detector.detector_record_access(1, 5000, fvx.OP_WRITE, 0, false);
   479→
   480→    // Thread 2: 같은 주소에 쓰기 (락 없음) → RACE!
   481→    detector.detector_record_access(2, 5000, fvx.OP_WRITE, 0, false);
