// ============================================================================
// FreeLang Collections 모듈 - 슬라이스 처리 및 데이터 구조
// ============================================================================
// 목표: Zero-Copy-DB에서 벡터, 배열, 인덱스 목록 등을 처리할 수 있도록 함
// 원리:
//   1. i64 슬라이스를 기본 컨테이너로 사용 (ID, 오프셋, 카운터 등)
//   2. 1급 함수 미지원 → map/filter를 구체적 파라미터로 구현
//   3. f32 슬라이스용 별도 함수 세트 제공 (벡터 연산용)
//   4. 이터레이터 패턴으로 순회 가능
// 구조:
//   - 상수 정의 (SORT_ASC, SORT_DESC)
//   - Iter, ZipPair 구조체
//   - @inline 집계 헬퍼
//   - 집계 함수 (sum, min, max, count, reduce)
//   - 검색 함수 (find, find_all, contains)
//   - 변환 함수 (filter_*, map_*)
//   - 조작 함수 (take, skip, zip, foreach)
//   - 정렬 함수 (sort_asc, sort_desc, sort_by)
//   - f32 전용 함수들
// ============================================================================

module collections {
    // === 상수 ===
    const SORT_ASC:  i32 = 1;
    const SORT_DESC: i32 = -1;

    // === 데이터 구조체 ===
    // 슬라이스 반복자
    struct Iter {
        data:   [i64];
        pos:    i32;
        length: i32;
    }

    // zip 결과용 쌍 구조체
    struct ZipPair {
        left:  i64;
        right: i64;
    }

    // === 이터레이터 함수 ===

    // 슬라이스로부터 이터레이터 생성
    func iter(data: [i64]) -> Iter {
        return Iter{
            data:   data,
            pos:    0,
            length: len(data),
        };
    }

    // 이터레이터가 다음 원소를 가지고 있는지 확인
    @inline
    func (it: *Iter) has_next() -> bool {
        return it.pos < it.length;
    }

    // 이터레이터에서 다음 원소 추출
    @inline
    func (it: *Iter) next() -> (i64, bool) {
        if !it.has_next() {
            return (0, false);
        }
        let val = it.data[it.pos];
        it.pos = it.pos + 1;
        return (val, true);
    }

    // === 집계 함수 ===

    // 슬라이스의 모든 원소 합계
    func sum(data: [i64]) -> i64 {
        let acc = i64(0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            acc = acc + data[i];
        }
        return acc;
    }

    // 슬라이스의 최솟값 (오버플로우 방지: i64 사용)
    func min(data: [i64]) -> (i64, bool) {
        if len(data) == 0 {
            return (0, false);
        }
        let min_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v < min_val {
                min_val = v;
            }
        }
        return (min_val, true);
    }

    // 슬라이스의 최댓값
    func max(data: [i64]) -> (i64, bool) {
        if len(data) == 0 {
            return (0, false);
        }
        let max_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v > max_val {
                max_val = v;
            }
        }
        return (max_val, true);
    }

    // 슬라이스의 원소 개수
    @inline
    func count(data: [i64]) -> i32 {
        return len(data);
    }

    // threshold 이상인 원소 개수
    func count_where(data: [i64], threshold: i64) -> i32 {
        let cnt = 0;
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] >= threshold {
                cnt = cnt + 1;
            }
        }
        return cnt;
    }

    // 누적 합계 (initial값에서 시작)
    func reduce(data: [i64], initial: i64) -> i64 {
        let acc = initial;
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            acc = acc + data[i];
        }
        return acc;
    }

    // === 검색 함수 ===

    // target과 일치하는 첫 번째 인덱스 반환
    func find(data: [i64], target: i64) -> (i32, bool) {
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] == target {
                return (i32(i), true);
            }
        }
        return (-1, false);
    }

    // target과 일치하는 모든 인덱스 수집
    func find_all(data: [i64], target: i64) -> [i32] {
        let indices = make([i32], 0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] == target {
                indices.push(i32(i));
            }
        }
        return indices;
    }

    // target이 슬라이스에 포함되어 있는지 확인
    func contains(data: [i64], target: i64) -> bool {
        let idx, found = find(data, target);
        return found;
    }

    // === 변환 함수 ===

    // 각 원소에 factor를 곱하기
    func map_fn(data: [i64], factor: i64) -> [i64] {
        let result = make([i64], len(data));
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            result[i] = data[i] * factor;
        }
        return result;
    }

    // 각 원소에 offset을 더하기
    func map_add(data: [i64], offset: i64) -> [i64] {
        let result = make([i64], len(data));
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            result[i] = data[i] + offset;
        }
        return result;
    }

    // threshold보다 큰 원소만 필터링
    func filter_gt(data: [i64], threshold: i64) -> [i64] {
        let result = make([i64], 0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] > threshold {
                result.push(data[i]);
            }
        }
        return result;
    }

    // [min, max] 범위에 있는 원소만 필터링
    func filter_range(data: [i64], min: i64, max: i64) -> [i64] {
        let result = make([i64], 0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            let v = data[i];
            if v >= min && v <= max {
                result.push(v);
            }
        }
        return result;
    }

    // === 조작 함수 ===

    // 앞의 n개 원소만 추출
    func take(data: [i64], n: i32) -> [i64] {
        if n >= len(data) {
            return data;
        }
        if n <= 0 {
            return make([i64], 0);
        }
        let result = make([i64], n);
        let i = 0;
        for i = 0; i < n; i = i + 1 {
            result[i] = data[i];
        }
        return result;
    }

    // 앞의 n개 원소 제외하고 나머지 반환
    func skip(data: [i64], n: i32) -> [i64] {
        if n >= len(data) {
            return make([i64], 0);
        }
        if n <= 0 {
            return data;
        }
        let result = make([i64], 0);
        let i = n;
        for i = n; i < len(data); i = i + 1 {
            result.push(data[i]);
        }
        return result;
    }

    // 두 슬라이스를 쌍으로 엮기 (짧은 쪽 기준)
    func zip(a: [i64], b: [i64]) -> [ZipPair] {
        let len_a = len(a);
        let len_b = len(b);
        let min_len = if len_a < len_b { len_a } else { len_b };
        let result = make([ZipPair], min_len);
        let i = 0;
        for i = 0; i < min_len; i = i + 1 {
            result[i] = ZipPair{ left: a[i], right: b[i] };
        }
        return result;
    }

    // 각 원소를 label과 함께 출력 (부수효과용)
    func foreach(data: [i64], label: string) {
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            print(label + "[" + i32_to_string(i32(i)) + "]=" + i64_to_string(data[i]));
        }
    }

    // === 정렬 함수 ===

    // 오름차순 정렬 (삽입 정렬)
    func sort_asc(data: [i64]) -> [i64] {
        let result = data;  // 복사 가정: FreeLang 런타임이 제공
        let len_val = len(result);
        let i = 1;
        for i = 1; i < len_val; i = i + 1 {
            let key = result[i];
            let j = i - 1;
            for j >= 0 && result[j] > key {
                result[j + 1] = result[j];
                j = j - 1;
            }
            result[j + 1] = key;
        }
        return result;
    }

    // 내림차순 정렬
    func sort_desc(data: [i64]) -> [i64] {
        let sorted = sort_asc(data);
        let len_val = len(sorted);
        let result = make([i64], len_val);
        let i = 0;
        for i = 0; i < len_val; i = i + 1 {
            result[i] = sorted[len_val - 1 - i];
        }
        return result;
    }

    // direction에 따라 정렬 (SORT_ASC / SORT_DESC)
    func sort_by(data: [i64], direction: i32) -> [i64] {
        if direction == SORT_ASC {
            return sort_asc(data);
        } else {
            return sort_desc(data);
        }
    }

    // === f32 전용 함수 (벡터 연산용) ===

    // f32 슬라이스의 합계
    func f32_sum(data: [f32]) -> f32 {
        let acc = f32(0.0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            acc = acc + data[i];
        }
        return acc;
    }

    // f32 슬라이스의 최솟값
    func f32_min(data: [f32]) -> (f32, bool) {
        if len(data) == 0 {
            return (0.0, false);
        }
        let min_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v < min_val {
                min_val = v;
            }
        }
        return (min_val, true);
    }

    // f32 슬라이스의 최댓값
    func f32_max(data: [f32]) -> (f32, bool) {
        if len(data) == 0 {
            return (0.0, false);
        }
        let max_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v > max_val {
                max_val = v;
            }
        }
        return (max_val, true);
    }

    // f32 슬라이스에서 threshold보다 큰 원소만 필터링
    func f32_filter_gt(data: [f32], threshold: f32) -> [f32] {
        let result = make([f32], 0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] > threshold {
                result.push(data[i]);
            }
        }
        return result;
    }

    // f32 슬라이스 오름차순 정렬
    func f32_sort_asc(data: [f32]) -> [f32] {
        let result = data;
        let len_val = len(result);
        let i = 1;
        for i = 1; i < len_val; i = i + 1 {
            let key = result[i];
            let j = i - 1;
            for j >= 0 && result[j] > key {
                result[j + 1] = result[j];
                j = j - 1;
            }
            result[j + 1] = key;
        }
        return result;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }

    @inline
    func i64_to_string(n: i64) -> string {
        return i32_to_string(i32(n));
    }
}

// === 테스트 시나리오 (주석) ===
// 기본 동작:
