        // b의 키-값 추가 또는 덮어쓰기
        for i = 0; i < len(b.object_keys); i = i + 1 {
            let key = b.object_keys[i];
            let val = b.object_vals[i];
            let found = false;
            let j = 0;
            for j = 0; j < len(result_keys); j = j + 1 {
                if result_keys[j] == key {
                    result_vals[j] = val;
                    found = true;
                    j = len(result_keys);  // break
                }
            }
            if !found {
                result_keys.push(key);
                result_vals.push(val);
            }
        }

        return (JsonValue{
            kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
            array_vals: make([JsonValue], 0), object_keys: result_keys, object_vals: result_vals,
        }, true);
    }

    // === 헬퍼 함수 ===

    @inline
    func i64_to_string(n: i64) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n < 0 { return "-" + i64_to_string(-n); }
        return "?";
    }

    // 배열을 구분자로 연결
    func join(parts: [string], sep: string) -> string {
        if len(parts) == 0 {
            return "";
        }
        let result = parts[0];
        let i = 1;
        for i = 1; i < len(parts); i = i + 1 {
            result = result + sep + parts[i];
        }
        return result;
    }
}

