   316→    // f32 슬라이스의 합계
   317→    func f32_sum(data: [f32]) -> f32 {
   318→        let acc = f32(0.0);
   319→        let i = 0;
   320→        for i = 0; i < len(data); i = i + 1 {
   321→            acc = acc + data[i];
   322→        }
   323→        return acc;
