   350→// === 테스트 시나리오 (주석) ===
   351→// 기본 동작:
   352→//   - chan_new(10) → Channel{ capacity: 10, count: 0, state: CHAN_OPEN }
   353→//   - ch.chan_send(42) → true
   354→//   - ch.chan_recv() → (42, true)
   355→//   - ch.chan_is_empty() → true
   356→//   - ch.chan_close()
