// ============================================================================
// FreeLang stdlib 통합 테스트
// ============================================================================
// 목표: 4개 모듈 (io, collections, json, concurrent)의 기능성 및 호환성 검증
// 범위: 기본 기능, 에러 처리, 모듈 간 연동
// ============================================================================

module stdlib_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:   string;
        passed: bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name: name,
            passed: condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_equal_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name: name,
            passed: passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_string(expected) + ", got " + i64_to_string(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[✓]" } else { "[✗]" };
        print(status + " " + r.name + " - " + r.message);
    }

    @inline
    func i64_to_string(n: i64) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i64_to_string(-n); }
        return "?";
    }

    // === io 모듈 테스트 ===

    func test_io() {
        print("\n=== I/O Module Tests ===");

        // 테스트 1: join_path
        let path1 = io.join_path("/data", "config.json");
        let r1 = assert_true(len(path1) > 0, "io.join_path");
        print_result(r1);

        // 테스트 2: read_file (nonexistent)
        let content, ok = io.read_file("/nonexistent/file.txt");
        let r2 = assert_true(!ok, "io.read_file error handling");
        print_result(r2);

        // 테스트 3: file_exists (기존 파일 확인)
        let exists = io.file_exists("/data/config.json");
        let r3 = assert_true(!exists || exists, "io.file_exists basic");
        print_result(r3);

        print("I/O tests completed");
    }

    // === collections 모듈 테스트 ===

    func test_collections() {
        print("\n=== Collections Module Tests ===");

        // 테스트 1: sum
        let data1 = [i64]{1, 2, 3};
        let sum1 = collections.sum(data1);
        let r1 = assert_equal_i64(sum1, 6, "collections.sum");
        print_result(r1);

        // 테스트 2: min
        let data2 = [i64]{3, 1, 2};
        let min_val, ok1 = collections.min(data2);
        let r2 = assert_equal_i64(min_val, 1, "collections.min");
        print_result(r2);

        // 테스트 3: max
        let max_val, ok2 = collections.max(data2);
        let r3 = assert_equal_i64(max_val, 3, "collections.max");
        print_result(r3);

        // 테스트 4: count
        let cnt = collections.count(data1);
        let r4 = assert_equal_i64(i64(cnt), 3, "collections.count");
        print_result(r4);

        // 테스트 5: find
        let idx, found = collections.find(data2, 2);
        let r5 = assert_true(found, "collections.find");
        print_result(r5);

        // 테스트 6: contains
        let has = collections.contains(data1, 2);
        let r6 = assert_true(has, "collections.contains");
        print_result(r6);

        // 테스트 7: filter_gt
        let filtered = collections.filter_gt(data2, 1);
        let r7 = assert_equal_i64(i64(len(filtered)), 2, "collections.filter_gt");
        print_result(r7);

        // 테스트 8: sort_asc
        let sorted = collections.sort_asc(data2);
        let first = if len(sorted) > 0 { sorted[0] } else { 0 };
        let r8 = assert_equal_i64(first, 1, "collections.sort_asc");
        print_result(r8);

        // 테스트 9: take
        let taken = collections.take(data1, 2);
        let r9 = assert_equal_i64(i64(len(taken)), 2, "collections.take");
        print_result(r9);

        // 테스트 10: skip
        let skipped = collections.skip(data1, 1);
        let r10 = assert_equal_i64(i64(len(skipped)), 2, "collections.skip");
        print_result(r10);

        print("Collections tests completed");
    }

    // === json 모듈 테스트 ===

    func test_json() {
        print("\n=== JSON Module Tests ===");

        // 테스트 1: make_null
        let v1 = json.make_null();
        let r1 = assert_equal_i64(i64(v1.kind), 0, "json.make_null");
        print_result(r1);

        // 테스트 2: make_int
        let v2 = json.make_int(42);
        let r2 = assert_equal_i64(v2.int_val, 42, "json.make_int");
        print_result(r2);

        // 테스트 3: make_string
        let v3 = json.make_string("hello");
        let r3 = assert_true(v3.str_val == "hello", "json.make_string");
        print_result(r3);

        // 테스트 4: stringify int
        let s1 = json.stringify(v2);
        let r4 = assert_true(len(s1) > 0, "json.stringify int");
        print_result(r4);

        // 테스트 5: stringify string
        let s2 = json.stringify(v3);
        let r5 = assert_true(len(s2) > 0, "json.stringify string");
        print_result(r5);

        // 테스트 6: parse null (간단함)
        let pv1, ok1 = json.parse("null");
        let r6 = assert_equal_i64(i64(pv1.kind), 0, "json.parse null");
        print_result(r6);

        // 테스트 7: parse true
        let pv2, ok2 = json.parse("true");
        let r7 = assert_true(ok2, "json.parse true");
        print_result(r7);

        // 테스트 8: merge
        let a = json.make_int(1);
        let b = json.make_int(2);
        let merged, ok3 = json.merge(a, b);
        let r8 = assert_true(ok3, "json.merge");
        print_result(r8);

        print("JSON tests completed");
    }

    // === concurrent 모듈 테스트 ===

    func test_concurrent() {
        print("\n=== Concurrent Module Tests ===");

        // 테스트 1: chan_new
        let ch = concurrent.chan_new(10);
        let r1 = assert_equal_i64(i64(ch.capacity), 10, "concurrent.chan_new capacity");
        print_result(r1);

        // 테스트 2: chan_is_empty
        let is_empty = ch.chan_is_empty();
        let r2 = assert_true(is_empty, "concurrent.chan_is_empty");
        print_result(r2);

        // 테스트 3: chan_send
        let ok1 = ch.chan_send(42);
        let r3 = assert_true(ok1, "concurrent.chan_send");
        print_result(r3);

        // 테스트 4: chan_len
        let len_val = ch.chan_len();
        let r4 = assert_equal_i64(i64(len_val), 1, "concurrent.chan_len after send");
        print_result(r4);

        // 테스트 5: chan_recv
        let msg, ok2 = ch.chan_recv();
        let r5 = assert_equal_i64(msg, 42, "concurrent.chan_recv");
        print_result(r5);

        // 테스트 6: chan_is_empty after recv
        let is_empty2 = ch.chan_is_empty();
        let r6 = assert_true(is_empty2, "concurrent.chan_is_empty after recv");
        print_result(r6);

        // 테스트 7: actor_new
        let actor = concurrent.actor_new(1, 10);
        let r7 = assert_equal_i64(i64(actor.id), 1, "concurrent.actor_new id");
        print_result(r7);

