struct HashRing {
    // 가상 노드 해시값 배열 (정렬됨)
    vnode_hashes:   [i64];
    // 각 가상 노드가 가리키는 물리 노드 ID
    vnode_owners:   [string];
    vnode_count:    i32;
    // 물리 노드 목록
