struct DistNode {
    id:         string;
    // RPC 레이어
    rpc_client: rpc.Client;
    rpc_server: rpc.Server;
    // 복제 레이어
    rep_group:  replication.ReplicaGroup;
    // 합의 레이어
    raft:       consensus.RaftNode;
    // 해시 링
    ring:       HashRing;
    // 통계
    total_puts: i64;
    total_gets: i64;
    total_routes: i64;
