func test_rpc() {
    print("\n=== RPC Tests ===");

    // Transport 파이프 생성
    let t_cli, t_srv = rpc.transport_pipe_new("client", "server");
    let cli = rpc.rpc_client_new(t_cli);
    let srv = rpc.rpc_server_new(t_srv);

    // 핸들러 등록 (ping)
