    print_result(r1);

    let r2 = assert_true(msg.msg_type == rpc.MSG_RESPONSE, "rpc response type");
    print_result(r2);
}
```

**테스트 시나리오 2: 복제 쿼럼** (~45줄)
```
func test_replication() {
    print("\n=== Replication Tests ===");

    // 3노드 그룹 생성
    let group = replication.group_new(2, 3);
    let n1 = replication.replica_node_new("node1", "localhost:8001");
    let n2 = replication.replica_node_new("node2", "localhost:8002");
    let n3 = replication.replica_node_new("node3", "localhost:8003");
    group.node_add(n1);
    group.node_add(n2);
    group.node_add(n3);

    // 쿼럼 쓰기 성공 (3개 alive)
    let err, ok = group.write_quorum("key1", 100);
    let r1 = assert_true(ok, "write_quorum 3/3 nodes alive");
    print_result(r1);

    // 노드 하나를 DEAD로 설정 (쿼럼 여전히 통과: 2/3)
    group.nodes[2].state = replication.REPLICA_DEAD;
    let err2, ok2 = group.write_quorum("key2", 200);
    let r2 = assert_true(ok2, "write_quorum 2/3 nodes alive (quorum met)");
    print_result(r2);

    // 두 노드 DEAD (쿼럼 실패: 1/3)
    group.nodes[1].state = replication.REPLICA_DEAD;
    let err3, ok3 = group.write_quorum("key3", 300);
    let r3 = assert_true(!ok3, "write_quorum 1/3 nodes alive (quorum failed)");
    print_result(r3);

    // 읽기 테스트
    group.nodes[1].state = replication.REPLICA_ALIVE;
    group.nodes[2].state = replication.REPLICA_ALIVE;
    let val, ok4 = group.read_quorum("key1");
    let r4 = assert_eq_i64(val, 100, "read_quorum key1");
    print_result(r4);
}
```

**테스트 시나리오 3: Raft 선거** (~50줄)
```
func test_raft() {
    print("\n=== Raft Consensus Tests ===");

    // 3노드 클러스터 생성
    let cluster = consensus.raft_cluster_new(3);

    // 초기 상태: 모두 FOLLOWER
    let r1 = assert_true(cluster.nodes[0].state == consensus.RAFT_FOLLOWER, "initial state follower");
    print_result(r1);

    // ELECTION_TIMEOUT tick 진행 → 첫 번째 노드 후보로 전환
    let t = 0;
    for t = 0; t < consensus.ELECTION_TIMEOUT + 1; t = t + 1 {
        cluster.tick_all();
    }

    // 누군가 리더로 선출되었는지 확인
    let leader_id, ok = cluster.nodes[0].find_leader(&cluster);
    let r2 = assert_true(ok, "leader elected after timeout");
    print_result(r2);

    // 리더에게 로그 항목 추가
    if ok {
        let leader_idx = leader_id;
        let log_idx = cluster.nodes[leader_idx].log_append(
            consensus.CMD_SET, "testkey", 999
        );
        let r3 = assert_true(log_idx >= 0, "log append to leader");
        print_result(r3);

        // 추가 tick으로 복제 완료
        for t = 0; t < 5; t = t + 1 {
            cluster.tick_all();
        }
    }
}
```

**테스트 시나리오 4: 통합 분산 API** (~45줄)
```
func test_distributed() {
    print("\n=== Distributed API Tests ===");

    // 3노드 클러스터 구성
    let node1 = distributed.dist_new("node1", 3);
    let node2 = distributed.dist_new("node2", 3);
    let node3 = distributed.dist_new("node3", 3);

    // 전역 레지스트리에 등록
    distributed.dist_register(&node1);
    distributed.dist_register(&node2);
    distributed.dist_register(&node3);

    // 링에 노드 추가
    node1.ring.ring_add("node1");
    node1.ring.ring_add("node2");
    node1.ring.ring_add("node3");

    // 해시 라우팅 확인
    let target = node1.dist_route("hello");
    let r1 = assert_true(len(target) > 0, "dist_route returns node id");
    print_result(r1);

    // 분산 put
    let err, ok = node1.dist_put("hello", 42);
    let r2 = assert_true(ok, "dist_put success");
    print_result(r2);

    // 분산 get (같은 노드에서)
    let val, ok2 = node1.dist_get("hello");
    let r3 = assert_eq_i64(val, 42, "dist_get returns correct value");
    print_result(r3);

    // 통계 출력
    let stats = node1.dist_stats();
    let r4 = assert_true(len(stats) > 0, "dist_stats non-empty");
    print_result(r4);
    print(stats);
}

func main() {
