// ============================================================================
// FreeLang Replication 모듈 - 쿼럼 기반 복제
// ============================================================================
// 목표: Zero-Copy-DB에서 고가용성을 위한 데이터 복제 구현
// 원리:
//   1. 쿼럼(Quorum) 쓰기: 과반수(factor/2+1) 이상 노드 성공 → 전체 성공
//   2. 복제 상태: ALIVE(정상), SUSPECT(의심), DEAD(다운)
//   3. 하트비트: tick 카운터로 노드 상태 감지
//   4. 내장 KV: 각 노드가 배열 기반 로컬 스토어 보유
// 구조:
//   - 상수 정의 (노드 상태, 복제 파라미터)
//   - ReplicaNode, ReplicaGroup 구조체
//   - 팩토리 함수
//   - 그룹 관리 (node_add, node_remove, alive_count)
//   - 쿼럼 연산 (write_quorum, read_quorum)
//   - 내장 KV 스토어
//   - 하트비트 관리
// ============================================================================

module replication {
    // === 상수: 노드 상태 ===
    const REPLICA_ALIVE:    i32 = 0;
    const REPLICA_SUSPECT:  i32 = 1;
    const REPLICA_DEAD:     i32 = 2;

    // === 상수: 복제 파라미터 ===
    const REPLICATION_FACTOR:  i32 = 3;
    const DEFAULT_QUORUM:      i32 = 2;    // factor/2 + 1
    const MAX_NODES:           i32 = 32;
    const MAX_KV_PER_NODE:     i32 = 256;

    // === 상수: 하트비트 타이머 (tick 단위) ===
    const HEARTBEAT_TIMEOUT:   i32 = 5;    // 5 tick 이상 응답 없으면 SUSPECT
    const SUSPECT_TIMEOUT:     i32 = 3;    // 3 tick 이상이면 DEAD

    // === 에러 코드 ===
    const REP_OK:              i32 = 0;
    const REP_ERR_QUORUM:      i32 = 10;   // 쿼럼 실패
    const REP_ERR_NO_ALIVE:    i32 = 11;   // 살아있는 노드 없음
    const REP_ERR_NOT_FOUND:   i32 = 12;   // 키를 찾을 수 없음
    const REP_ERR_DUPLICATE:   i32 = 13;   // 중복된 노드

    // === 데이터 구조체 ===
    // 복제 그룹의 멤버 노드
    struct ReplicaNode {
        id:              string;
        addr:            string;     // "node1:8001" 형태
        state:           i32;        // REPLICA_ALIVE/SUSPECT/DEAD
        last_heartbeat:  i32;        // 마지막 하트비트 tick

        // 내장 KV 스토어 (배열 기반)
        store_keys:      [string];
        store_vals:      [i64];
        store_count:     i32;
    }

    // 복제 그룹 (여러 ReplicaNode로 구성)
    struct ReplicaGroup {
        nodes:          [ReplicaNode];
        node_count:     i32;
        quorum:         i32;        // 필요한 최소 응답 수 (보통 factor/2+1)
        factor:         i32;        // 복제 인수 (보통 3)
        current_tick:   i32;        // 현재 tick (하트비트 계산용)
    }

    // === 팩토리 함수 ===

    // ReplicaGroup 생성
    func group_new(quorum: i32, factor: i32) -> ReplicaGroup {
        return ReplicaGroup{
            nodes:          make([ReplicaNode], MAX_NODES),
            node_count:     0,
            quorum:         quorum,
            factor:         factor,
            current_tick:   0,
        };
    }

    // ReplicaNode 생성
    func replica_node_new(id: string, addr: string) -> ReplicaNode {
        return ReplicaNode{
            id:              id,
            addr:            addr,
            state:           REPLICA_ALIVE,
            last_heartbeat:  0,
            store_keys:      make([string], MAX_KV_PER_NODE),
            store_vals:      make([i64], MAX_KV_PER_NODE),
            store_count:     0,
        };
    }

    // === 그룹 관리 함수 ===

    // 그룹에 노드 추가
    func (g: *ReplicaGroup) node_add(node: ReplicaNode) -> bool {
        if g.node_count >= MAX_NODES {
            return false;
        }
        // 중복 확인
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].id == node.id {
                return false;  // 중복 노드
            }
        }
        g.nodes[g.node_count] = node;
        g.node_count = g.node_count + 1;
        return true;
    }

    // 그룹에서 노드 제거
    func (g: *ReplicaGroup) node_remove(id: string) -> bool {
        let i = 0;
        let j = 0;
        let found = false;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].id != id {
                g.nodes[j] = g.nodes[i];
                j = j + 1;
            } else {
                found = true;
            }
        }
        if found {
            g.node_count = j;
        }
        return found;
    }

    // 노드 ID로 인덱스 찾기
    func (g: *ReplicaGroup) node_find(id: string) -> (i32, bool) {
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].id == id {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // 살아있는 노드 수 카운트
    func (g: *ReplicaGroup) alive_count() -> i32 {
        let count = 0;
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].state == REPLICA_ALIVE {
                count = count + 1;
            }
        }
        return count;
    }

    // === 쿼럼 쓰기/읽기 (핵심) ===

    // 쿼럼 쓰기: 모든 ALIVE 노드에 쓰고 quorum개 이상 성공 필요
    func (g: *ReplicaGroup) write_quorum(key: string, val: i64) -> (i32, bool) {
        let alive = g.alive_count();
        if alive == 0 {
            return (REP_ERR_NO_ALIVE, false);
        }

        // 모든 ALIVE 노드에 쓰기
        let acks = 0;
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].state == REPLICA_ALIVE {
                let ok = g.nodes[i].local_set(key, val);
                if ok {
                    acks = acks + 1;
                }
            }
        }

        // 쿼럼 확인 (quorum개 이상 성공)
        if acks < g.quorum {
            return (REP_ERR_QUORUM, false);
        }
        return (REP_OK, true);
    }

    // 쿼럼 읽기: 첫 번째 ALIVE 노드에서 읽기 (단순화)
    func (g: *ReplicaGroup) read_quorum(key: string) -> (i64, bool) {
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].state == REPLICA_ALIVE {
                return g.nodes[i].local_get(key);
            }
        }
        return (0, false);  // 살아있는 노드 없음
    }

    // === 내장 KV 스토어 함수 ===

    // 로컬 Set (배열 기반, 없으면 추가, 있으면 업데이트)
    func (n: *ReplicaNode) local_set(key: string, val: i64) -> bool {
        let i = 0;
        // 기존 키 찾기
        for i = 0; i < n.store_count; i = i + 1 {
            if n.store_keys[i] == key {
                n.store_vals[i] = val;
                return true;
            }
        }
        // 새 키 추가
        if n.store_count >= MAX_KV_PER_NODE {
            return false;  // 스토어 가득 참
        }
        n.store_keys[n.store_count] = key;
        n.store_vals[n.store_count] = val;
        n.store_count = n.store_count + 1;
        return true;
    }

    // 로컬 Get
    func (n: *ReplicaNode) local_get(key: string) -> (i64, bool) {
        let i = 0;
        for i = 0; i < n.store_count; i = i + 1 {
            if n.store_keys[i] == key {
                return (n.store_vals[i], true);
            }
        }
        return (0, false);
    }

    // 로컬 Delete
    func (n: *ReplicaNode) local_delete(key: string) -> bool {
        let i = 0;
        let j = 0;
        let found = false;
        for i = 0; i < n.store_count; i = i + 1 {
            if n.store_keys[i] != key {
                n.store_keys[j] = n.store_keys[i];
                n.store_vals[j] = n.store_vals[i];
                j = j + 1;
            } else {
                found = true;
            }
        }
        if found {
            n.store_count = j;
        }
        return found;
    }

    // 로컬 스토어 크기
    func (n: *ReplicaNode) local_count() -> i32 {
        return n.store_count;
    }

    // === 하트비트 관리 ===

    // 하트비트 기록 (응답 받을 때마다 호출)
    func (g: *ReplicaGroup) record_heartbeat(node_id: string, tick: i32) -> bool {
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].id == node_id {
                g.nodes[i].last_heartbeat = tick;
                return true;
            }
        }
        return false;
    }

    // 하트비트 체크: 모든 노드의 상태를 업데이트
    // tick 경과에 따라 ALIVE → SUSPECT → DEAD로 전환
    func (g: *ReplicaGroup) heartbeat_check(current_tick: i32) {
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            let age = current_tick - g.nodes[i].last_heartbeat;

            // 상태 전환 로직
            if age < SUSPECT_TIMEOUT {
                g.nodes[i].state = REPLICA_ALIVE;
            } else if age < HEARTBEAT_TIMEOUT {
                g.nodes[i].state = REPLICA_SUSPECT;
            } else {
                g.nodes[i].state = REPLICA_DEAD;
            }
        }
    }

    // === 통계 함수 ===

    func (g: *ReplicaGroup) group_stats() -> string {
        let alive = g.alive_count();
        let suspect_count = 0;
        let dead_count = 0;
        let i = 0;
        for i = 0; i < g.node_count; i = i + 1 {
            if g.nodes[i].state == REPLICA_SUSPECT {
                suspect_count = suspect_count + 1;
            } else if g.nodes[i].state == REPLICA_DEAD {
                dead_count = dead_count + 1;
            }
        }
        let msg = "[ReplicaGroup] nodes=" + i32_to_string(g.node_count) +
                  " alive=" + i32_to_string(alive) +
                  " suspect=" + i32_to_string(suspect_count) +
                  " dead=" + i32_to_string(dead_count) +
                  " quorum=" + i32_to_string(g.quorum);
        return msg;
    }

    func (n: *ReplicaNode) node_stats() -> string {
        let state_str = if n.state == REPLICA_ALIVE {
            "ALIVE"
        } else if n.state == REPLICA_SUSPECT {
            "SUSPECT"
        } else {
            "DEAD"
        };
        let msg = "[ReplicaNode] id=" + n.id + " state=" + state_str + " kv=" + i32_to_string(n.store_count);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }
}

// === 테스트 시나리오 (주석) ===
//
// 기본 동작:
//   - group_new(2, 3) → ReplicaGroup{ quorum: 2, factor: 3 }
//   - replica_node_new("node1", "localhost:8001") → ReplicaNode
