// ============================================================================
// FreeLang Consensus 모듈 - Raft 합의 알고리즘
// ============================================================================
// 목표: 분산 노드 간 상태 일관성을 보장하는 Raft 리더 선출 & 로그 복제
// 원리:
//   1. 3가지 노드 상태: FOLLOWER (추종자), CANDIDATE (후보), LEADER (리더)
//   2. 선거 타임아웃 기반 리더 선출 (결정론적)
//   3. 로그: 각 항목(index, term, command) 기록
//   4. 복제: 리더가 모든 팔로워에 로그 항목 전송
// 구조:
//   - 상수 정의 (상태, 타임아웃, 명령)
//   - LogEntry, RaftNode, RaftCluster 구조체
//   - 팩토리 함수
//   - Tick 드라이버 (결정론적 시뮬레이션)
//   - 선거 로직 (become_candidate, request_vote)
//   - 로그 복제 (append_entries, log_append)
// ============================================================================

module consensus {
    // === 상수: 노드 상태 ===
    const RAFT_FOLLOWER:   i32 = 0;
    const RAFT_CANDIDATE:  i32 = 1;
    const RAFT_LEADER:     i32 = 2;

    // === 상수: 타이머 (tick 단위) ===
    const ELECTION_TIMEOUT:    i32 = 10;   // 리더 선출 타임아웃
    const HEARTBEAT_INTERVAL:  i32 = 3;    // 리더 하트비트 간격

    // === 상수: 제한값 ===
    const MAX_LOG_ENTRIES:   i32 = 256;
    const MAX_NODES:         i32 = 32;
    const NONE:              i32 = -1;     // voted_for 초기값

    // === 상수: 명령 타입 ===
    const CMD_NOP:  i64 = 0;   // No-op (하트비트)
    const CMD_SET:  i64 = 1;   // Set 명령
    const CMD_DEL:  i64 = 2;   // Delete 명령

    // === 데이터 구조체 ===
    // Raft 로그 항목
    struct LogEntry {
        index:      i32;
        term:       i32;
        command:    i64;       // CMD_SET / CMD_DEL / CMD_NOP
        key:        string;
        val:        i64;
        committed:  bool;
    }

    // Raft 노드 (상태 머신)
    struct RaftNode {
        id:              i32;
        state:           i32;        // RAFT_FOLLOWER / CANDIDATE / LEADER

        // 영속 상태 (persistent)
        current_term:    i32;        // 현재 term (처음에 0)
        voted_for:       i32;        // 투표한 후보 ID (NONE이면 미투표)

        // 휘발성 상태 (volatile)
        commit_index:    i32;        // 커밋된 로그 인덱스
        last_applied:    i32;        // 적용한 로그 인덱스

        // 리더 전용
        next_index:      [i32];      // 각 팔로워별 다음 전송 인덱스
        match_index:     [i32];      // 각 팔로워별 복제 완료 인덱스

        // 로그
        log:             [LogEntry];
        log_count:       i32;

        // 타이머
        tick_elapsed:    i32;        // 경과 tick
        votes_received:  i32;        // 받은 투표 수 (후보 전용)
    }

    // Raft 클러스터
    struct RaftCluster {
        nodes:       [RaftNode];
        node_count:  i32;
        total_ticks: i32;
    }

    // === 팩토리 함수 ===

    // RaftNode 생성
    func raft_new(id: i32, cluster_size: i32) -> RaftNode {
        return RaftNode{
            id:              id,
            state:           RAFT_FOLLOWER,
            current_term:    0,
            voted_for:       NONE,
            commit_index:    0,
            last_applied:    0,
            next_index:      make([i32], cluster_size),
            match_index:     make([i32], cluster_size),
            log:             make([LogEntry], MAX_LOG_ENTRIES),
            log_count:       0,
            tick_elapsed:    0,
            votes_received:  0,
        };
    }

    // RaftCluster 생성
    func raft_cluster_new(node_count: i32) -> RaftCluster {
        let nodes = make([RaftNode], MAX_NODES);
        let i = 0;
        for i = 0; i < node_count; i = i + 1 {
            nodes[i] = raft_new(i, node_count);
        }
        return RaftCluster{
            nodes:       nodes,
            node_count:  node_count,
            total_ticks: 0,
        };
    }

    // === 선거 로직 ===

    // 후보자로 전환 (새로운 선거 시작)
    func (node: *RaftNode) become_candidate(cluster: *RaftCluster) {
        node.state = RAFT_CANDIDATE;
        node.current_term = node.current_term + 1;
        node.voted_for = node.id;        // 자신에게 투표
        node.votes_received = 1;         // 자기 투표 1표
        node.tick_elapsed = 0;
        // 모든 다른 노드에게 RequestVote 전송 (시뮬레이션: broadcast_vote)
        let i = 0;
        for i = 0; i < cluster.node_count; i = i + 1 {
            if i != node.id {
                cluster.nodes[i].process_request_vote(node.id, node.current_term);
            }
        }
    }

    // 리더로 전환
    func (node: *RaftNode) become_leader(cluster: *RaftCluster) {
        node.state = RAFT_LEADER;
        node.tick_elapsed = 0;
        // next_index 초기화 (각 팔로워별 로그 끝 다음)
        let i = 0;
        for i = 0; i < cluster.node_count; i = i + 1 {
            node.next_index[i] = node.log_count;
            node.match_index[i] = -1;
        }
    }

    // RequestVote RPC 처리 (간단화 버전)
    func (node: *RaftNode) process_request_vote(candidate_id: i32, term: i32) {
        // 이전 term이면 무시
        if term < node.current_term {
            return;
        }
        // term 업데이트
        if term > node.current_term {
            node.current_term = term;
            node.state = RAFT_FOLLOWER;
            node.voted_for = NONE;
        }
        // 아직 투표하지 않았으면 투표
        if node.voted_for == NONE {
            node.voted_for = candidate_id;
        }
    }

    // RequestVote RPC 호출 (리더 선거)
    func (node: *RaftNode) request_vote(
        term: i32, candidate_id: i32,
        last_log_index: i32, last_log_term: i32
    ) -> (i32, bool) {
        // 이전 term이면 거부
        if term < node.current_term {
            return (node.current_term, false);
        }
        // term 업데이트
        if term > node.current_term {
            node.current_term = term;
            node.state = RAFT_FOLLOWER;
            node.voted_for = NONE;
        }
        // 이미 투표했으면 거부
        if node.voted_for != NONE && node.voted_for != candidate_id {
            return (node.current_term, false);
        }
        // 로그 최신성 확인
        let my_last_idx = node.log_count - 1;
        let my_last_term = if node.log_count > 0 {
            node.log[my_last_idx].term
        } else {
            0
        };
        if last_log_term < my_last_term {
            return (node.current_term, false);
        }
        if last_log_term == my_last_term && last_log_index < my_last_idx {
            return (node.current_term, false);
        }
        // 투표 승인
        node.voted_for = candidate_id;
        node.tick_elapsed = 0;
        return (node.current_term, true);
    }

    // === 로그 복제 ===

    // 로그 항목 추가 (리더 전용)
    func (node: *RaftNode) log_append(cmd: i64, key: string, val: i64) -> i32 {
        if node.state != RAFT_LEADER {
            return -1;  // 리더만 로그 추가 가능
        }
        if node.log_count >= MAX_LOG_ENTRIES {
            return -1;  // 로그 가득 참
        }
        let idx = node.log_count;
        node.log[idx] = LogEntry{
            index:      idx,
            term:       node.current_term,
            command:    cmd,
            key:        key,
            val:        val,
            committed:  false,
        };
        node.log_count = node.log_count + 1;
        return idx;
    }

    // AppendEntries RPC 처리
    func (node: *RaftNode) append_entries(
        term: i32, leader_id: i32,
        prev_log_index: i32, prev_log_term: i32,
        entries: [LogEntry], leader_commit: i32
    ) -> (i32, bool) {
        // 이전 term이면 거부
        if term < node.current_term {
            return (node.current_term, false);
        }
        // term 업데이트
        if term > node.current_term {
            node.current_term = term;
            node.state = RAFT_FOLLOWER;
            node.voted_for = NONE;
        }
        node.tick_elapsed = 0;  // 하트비트 수신 → 타이머 리셋

        // 로그 이전 항목 확인 (생략: 복잡함)

        // 커밋 인덱스 업데이트
        if leader_commit > node.commit_index {
            let new_commit = if leader_commit < node.log_count - 1 {
                leader_commit
            } else {
                node.log_count - 1
            };
            node.commit_index = new_commit;
        }

        return (node.current_term, true);
    }

    // 커밋된 항목 적용
    func (node: *RaftNode) apply_entries() -> i32 {
        let applied = 0;
        let i = node.last_applied;
        for i = node.last_applied; i < node.commit_index; i = i + 1 {
            if i >= 0 && i < node.log_count {
                node.log[i].committed = true;
                applied = applied + 1;
            }
        }
        node.last_applied = node.commit_index;
        return applied;
    }

    // === Tick 드라이버 (결정론적 시뮬레이션) ===

    // 노드 상태 머신 (한 번의 tick)
    func (node: *RaftNode) raft_tick(cluster: *RaftCluster) {
        node.tick_elapsed = node.tick_elapsed + 1;

        if node.state == RAFT_FOLLOWER {
            // 노드 ID 기반 선거 타임아웃 오프셋 (분할 투표 방지)
            let timeout = ELECTION_TIMEOUT + node.id * 2;
            if node.tick_elapsed >= timeout {
                node.become_candidate(cluster);
            }
        }

        if node.state == RAFT_CANDIDATE {
            // 후보: 투표 결과를 확인해서 리더로 전환할지 결정
            let quorum = cluster.node_count / 2 + 1;
            if node.votes_received >= quorum {
                node.become_leader(cluster);
            }
            // 타임아웃 재선거 (간단화)
            let timeout = ELECTION_TIMEOUT + node.id * 2;
            if node.tick_elapsed >= timeout * 2 {
                node.become_candidate(cluster);
            }
        }

        if node.state == RAFT_LEADER {
            // 리더: 하트비트 전송
            if node.tick_elapsed % HEARTBEAT_INTERVAL == 0 {
                let i = 0;
                for i = 0; i < cluster.node_count; i = i + 1 {
                    if i != node.id {
                        // AppendEntries RPC 전송 (간단화: direct call)
                        let empty_entries = make([LogEntry], 0);
                        cluster.nodes[i].append_entries(
                            node.current_term, node.id,
                            -1, 0, empty_entries, node.commit_index
                        );
                    }
                }
            }
        }
    }

    // 클러스터 전체 tick
    func (cluster: *RaftCluster) tick_all() {
        let i = 0;
        for i = 0; i < cluster.node_count; i = i + 1 {
            cluster.nodes[i].raft_tick(cluster);
        }
        cluster.total_ticks = cluster.total_ticks + 1;
    }

    // === 헬퍼 함수 ===

    // 현재 리더 찾기
    func (cluster: *RaftCluster) find_leader() -> (i32, bool) {
        let i = 0;
        for i = 0; i < cluster.node_count; i = i + 1 {
            if cluster.nodes[i].state == RAFT_LEADER {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // === 통계 함수 ===

    func (node: *RaftNode) raft_stats() -> string {
        let state_str = if node.state == RAFT_FOLLOWER {
            "FOLLOWER"
        } else if node.state == RAFT_CANDIDATE {
            "CANDIDATE"
        } else {
            "LEADER"
        };
        let msg = "[RaftNode " + i32_to_string(node.id) + "] state=" + state_str +
                  " term=" + i32_to_string(node.current_term) +
                  " log=" + i32_to_string(node.log_count);
        return msg;
    }

    func (cluster: *RaftCluster) cluster_stats() -> string {
        let leader_id, has_leader = cluster.find_leader();
        let leader_str = if has_leader {
            i32_to_string(leader_id)
        } else {
            "none"
        };
        let msg = "[RaftCluster] nodes=" + i32_to_string(cluster.node_count) +
                  " leader=" + leader_str + " ticks=" + i32_to_string(cluster.total_ticks);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }
}

// === 테스트 시나리오 (주석) ===
//
// Raft 기본 동작:
//   - raft_cluster_new(3) → RaftCluster{ 3개 노드, 모두 FOLLOWER }
//
// 선거 시뮬레이션:
//   1. tick 0-9: 아무 일 안 일어남 (ELECTION_TIMEOUT=10 미달)
//   2. tick 10: 노드 0 (timeout=10+0*2=10) → CANDIDATE 전환
//   3. tick 11: 노드 1 (timeout=10+1*2=12) 아직 FOLLOWER
//   4. tick 12: 노드 0 리더 당선 (quorum=2, votes=1+α)
//
// 하트비트:
//   - 리더: tick_elapsed % HEARTBEAT_INTERVAL == 0 → AppendEntries 전송
//   - 팔로워: AppendEntries 수신 → tick_elapsed 리셋
//
// 로그 복제:
//   - leader.log_append(CMD_SET, "key", 100) → log_count 증가
//   - leader가 모든 팔로워에게 항목 전송
//   - quorum개 복제 완료 → commit_index 증가
//

