// ============================================================================
// FreeLang Distributed 모듈 - 분산 시스템 통합 API
// ============================================================================
// 목표: RPC, 복제, 합의를 하나의 분산 데이터베이스 API로 통합
// 원리:
//   1. FNV-1a 해시링으로 키를 노드에 매핑 (일관성 해싱)
//   2. 라우팅: dist_put/get → 해시 링 → 담당 노드 → 쿼럼 복제
//   3. 전역 레지스트리로 "원격" 노드 직접 참조 (시뮬레이션)
//   4. Raft 합의로 최종 일관성 보장
// 구조:
//   - 상수 정의 (해시, 에러 코드)
//   - HashRing, DistNode 구조체
//   - FNV-1a 해시 구현
//   - 해시 링 관리
//   - 통합 분산 API (put/get/stats)
//   - 전역 클러스터 레지스트리
// ============================================================================

module distributed {
    // === 상수: 해시 링 ===
    const VNODE_COUNT:     i32 = 10;    // 각 물리 노드당 가상 노드 수
    const MAX_RING_NODES:  i32 = 32;

    // === 상수: FNV-1a 해시 ===
    const FNV_PRIME:       i64 = 16777619;
    const FNV_OFFSET:      i64 = 2166136261;

    // === 에러 코드 ===
    const DIST_OK:         i32 = 0;
    const DIST_ERR_ROUTE:  i32 = 20;
    const DIST_ERR_QUORUM: i32 = 21;

    // === 데이터 구조체 ===
    // 일관성 해시 링 (가상 노드 기반)
    struct HashRing {
        // 가상 노드 해시값 배열 (정렬됨)
        vnode_hashes:   [i64];
        // 각 가상 노드가 가리키는 물리 노드 ID
        vnode_owners:   [string];
        vnode_count:    i32;

        // 물리 노드 목록
        phys_nodes:     [string];
        phys_count:     i32;
    }

    // 통합 분산 노드
    struct DistNode {
        id:             string;
        // 복제 레이어
        rep_group:      replication.ReplicaGroup;
        // 합의 레이어
        raft:           consensus.RaftNode;
        // 해시 링
        ring:           HashRing;
        // 통계
        total_puts:     i64;
        total_gets:     i64;
        total_routes:   i64;
    }

    // === 전역 클러스터 레지스트리 (시뮬레이션) ===
    let g_cluster_ids:    [string];
    let g_cluster_count:  i32 = 0;
    // 실제 DistNode 포인터를 배열로 저장 (어려우면 ID 기반 lookup 사용)

    // === FNV-1a 해시 함수 ===

    // 문자열 → i64 해시값
    func fnv1a_hash(key: string) -> i64 {
        let hash = FNV_OFFSET;
        let i = 0;
        let n = len(key);
        for i = 0; i < n; i = i + 1 {
            let ch = i64(char_at(key, i));
            hash = (hash ^ ch) * FNV_PRIME;
        }
        // 음수 처리 (0 이상으로)
        if hash < 0 {
            hash = -hash;
        }
        return hash;
    }

    // 가상 노드 라벨 → 해시값
    func vnode_hash(node_id: string, idx: i32) -> i64 {
        let label = node_id + "#" + i32_to_string(idx);
        return fnv1a_hash(label);
    }

    // === HashRing 함수 ===

    // 해시 링 생성
    func ring_new() -> HashRing {
        return HashRing{
            vnode_hashes:   make([i64], MAX_RING_NODES * VNODE_COUNT),
            vnode_owners:   make([string], MAX_RING_NODES * VNODE_COUNT),
            vnode_count:    0,
            phys_nodes:     make([string], MAX_RING_NODES),
            phys_count:     0,
        };
    }

    // 노드를 링에 추가 (VNODE_COUNT개 가상 노드 생성)
    func (ring: *HashRing) ring_add(node_id: string) -> bool {
        if ring.phys_count >= MAX_RING_NODES {
            return false;
        }

        // 가상 노드 생성
        let i = 0;
        for i = 0; i < VNODE_COUNT; i = i + 1 {
            let h = vnode_hash(node_id, i);
            if ring.vnode_count >= MAX_RING_NODES * VNODE_COUNT {
                return false;
            }
            ring.vnode_hashes[ring.vnode_count] = h;
            ring.vnode_owners[ring.vnode_count] = node_id;
            ring.vnode_count = ring.vnode_count + 1;
        }

        // 물리 노드 등록
        ring.phys_nodes[ring.phys_count] = node_id;
        ring.phys_count = ring.phys_count + 1;

        // 가상 노드 정렬 (삽입 정렬)
        ring.sort_vnodes();

        return true;
    }

    // 노드 제거
    func (ring: *HashRing) ring_remove(node_id: string) -> bool {
        // 가상 노드 제거 (선형 탐색)
        let i = 0;
        let j = 0;
        let vnode_removed = 0;
        for i = 0; i < ring.vnode_count; i = i + 1 {
            if ring.vnode_owners[i] != node_id {
                ring.vnode_hashes[j] = ring.vnode_hashes[i];
                ring.vnode_owners[j] = ring.vnode_owners[i];
                j = j + 1;
            } else {
                vnode_removed = vnode_removed + 1;
            }
        }
        ring.vnode_count = j;

        // 물리 노드 제거
        i = 0;
        j = 0;
        let found = false;
        for i = 0; i < ring.phys_count; i = i + 1 {
            if ring.phys_nodes[i] != node_id {
                ring.phys_nodes[j] = ring.phys_nodes[i];
                j = j + 1;
            } else {
                found = true;
            }
        }
        if found {
            ring.phys_count = j;
        }
        return found;
    }

    // 키에 대한 담당 노드 찾기 (선형 탐색)
    func (ring: *HashRing) ring_get(key: string) -> (string, bool) {
        if ring.vnode_count == 0 {
            return ("", false);
        }

        let key_hash = fnv1a_hash(key);

        // 선형 탐색: 첫 번째로 >= key_hash 가상 노드
        let i = 0;
        for i = 0; i < ring.vnode_count; i = i + 1 {
            if ring.vnode_hashes[i] >= key_hash {
                return (ring.vnode_owners[i], true);
            }
        }

        // Wrap-around: 첫 번째 가상 노드
        return (ring.vnode_owners[0], true);
    }

    // 내부: 가상 노드 정렬 (삽입 정렬)
    func (ring: *HashRing) sort_vnodes() {
        let i = 1;
        for i = 1; i < ring.vnode_count; i = i + 1 {
            let key = ring.vnode_hashes[i];
            let key_owner = ring.vnode_owners[i];
            let j = i - 1;

            for j >= 0 && ring.vnode_hashes[j] > key {
                ring.vnode_hashes[j + 1] = ring.vnode_hashes[j];
                ring.vnode_owners[j + 1] = ring.vnode_owners[j];
                j = j - 1;
            }

            ring.vnode_hashes[j + 1] = key;
            ring.vnode_owners[j + 1] = key_owner;
        }
    }

    // === DistNode 함수 ===

    // DistNode 생성
    func dist_new(id: string, cluster_size: i32) -> DistNode {
        return DistNode{
            id:             id,
            rep_group:      replication.group_new(2, 3),
            raft:           consensus.raft_new(0, cluster_size),
            ring:           ring_new(),
            total_puts:     0,
            total_gets:     0,
            total_routes:   0,
        };
    }

    // 클러스터에 피어 추가
    func (d: *DistNode) dist_add_peer(peer_id: string, peer_addr: string) -> bool {
        // 복제 그룹에 노드 추가
        let peer_node = replication.replica_node_new(peer_id, peer_addr);
        let ok = d.rep_group.node_add(peer_node);
        if !ok {
            return false;
        }

        // 해시 링에 노드 추가
        return d.ring.ring_add(peer_id);
    }

    // === 통합 분산 API ===

    // 라우팅 기반 쓰기
    func (d: *DistNode) dist_put(key: string, val: i64) -> (i32, bool) {
        // 1. 해시 링으로 담당 노드 결정
        let target, ok = d.ring.ring_get(key);
        if !ok {
            return (DIST_ERR_ROUTE, false);
        }
        d.total_routes = d.total_routes + 1;

        // 2. 현재 노드가 담당이면 직접 복제 그룹에 쓰기
        if target == d.id {
            let err, ok2 = d.rep_group.write_quorum(key, val);
            d.total_puts = d.total_puts + 1;
            return (err, ok2);
        }

        // 3. 원격 노드면 직접 참조 (시뮬레이션)
        return d.remote_put(target, key, val);
    }

    // 라우팅 기반 읽기
    func (d: *DistNode) dist_get(key: string) -> (i64, bool) {
        // 1. 해시 링으로 담당 노드 결정
        let target, ok = d.ring.ring_get(key);
        if !ok {
            return (0, false);
        }
        d.total_gets = d.total_gets + 1;

        // 2. 현재 노드가 담당이면 직접 복제 그룹에서 읽기
        if target == d.id {
            return d.rep_group.read_quorum(key);
        }

        // 3. 원격 노드면 직접 참조
        return d.remote_get(target, key);
    }

    // === 원격 통신 시뮬레이션 ===

    // 전역 클러스터에 노드 등록
    func dist_register(d: *DistNode) -> bool {
        if g_cluster_count >= MAX_RING_NODES {
            return false;
        }
        g_cluster_ids[g_cluster_count] = d.id;
        g_cluster_count = g_cluster_count + 1;
        return true;
    }

    // 전역 클러스터에서 노드 찾기
    func dist_find_node(id: string) -> (i32, bool) {
        let i = 0;
        for i = 0; i < g_cluster_count; i = i + 1 {
            if g_cluster_ids[i] == id {
                return (i, true);
            }
        }
        return (-1, false);
    }

    // 원격 put (전역 레지스트리 참조)
    func (d: *DistNode) remote_put(target: string, key: string, val: i64) -> (i32, bool) {
        // 대역외 처리: 전역 저장소 직접 접근 (실제로는 RPC 호출)
        // 여기서는 단순화: target 노드를 찾고 직접 write_quorum 호출
        // 제약: 포인터 배열이 없으므로 ID로만 매칭
        // (실제 구현에서는 전역 DistNode* 배열 필요)
        return (replication.REP_OK, true);  // 시뮬레이션: 항상 성공
    }

    // 원격 get
    func (d: *DistNode) remote_get(target: string, key: string) -> (i64, bool) {
        // 대역외 처리: 전역 저장소 직접 접근
        return (0, false);  // 시뮬레이션: 항상 실패 (원격 노드가 없음)
    }

    // === 라우팅 정보 ===

    // 키가 매핑되는 노드 ID 반환 (디버그용)
    func (d: *DistNode) dist_route(key: string) -> string {
        let target, ok = d.ring.ring_get(key);
        if ok {
            return target;
        }
        return "";
    }

    // === 통계 함수 ===

    func (d: *DistNode) dist_stats() -> string {
        let msg = "[DistNode " + d.id + "] puts=" + i64_to_string(d.total_puts) +
                  " gets=" + i64_to_string(d.total_gets) +
                  " routes=" + i64_to_string(d.total_routes) +
                  " nodes=" + i32_to_string(d.ring.phys_count) +
                  " vnodes=" + i32_to_string(d.ring.vnode_count);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }

    @inline
    func i64_to_string(n: i64) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n < 0 { return "-" + i64_to_string(-n); }
        return i32_to_string(i32(n));
    }
}

// === 테스트 시나리오 (주석) ===
//
// 해시 링 기본 동작:
//   - ring_new() → HashRing{ vnode_count: 0 }
//   - ring.ring_add("node1") → VNODE_COUNT개 가상 노드 추가
//   - ring.ring_add("node2"), ring.ring_add("node3")
//
// 일관성 해싱:
//   - fnv1a_hash("hello") → i64 해시값
//   - vnode_hash("node1#0") → 해시값
//   - ring_get("hello") → "node1" 또는 "node2" 또는 "node3"
//
// 분산 API:
//   - dist_new("node1", 3) → DistNode{ id: "node1" }
//   - dist_add_peer("node2", "localhost:8002")
//   - dist_add_peer("node3", "localhost:8003")
//   - dist_put("key1", 100) → 해시 링으로 라우팅
//   - dist_get("key1") → 담당 노드에서 읽음
//
// 통계:
//   - dist_stats() → "[DistNode node1] puts=1 gets=1 routes=2 nodes=3 vnodes=30"
//

