        for i = 0; i < TEST_KEYS; i = i + 1 {
            let key = make_test_key(i);
            let val = make_test_value(i);

            // 쿼럼 쓰기 (현재 노드만 있으므로 quorum=1)
            let node_copy = node;
            node_copy.rep_group.nodes[0].state = replication.REPLICA_ALIVE;

            let err, ok = node.rep_group.write_quorum(key, val);
            if ok {
                result.total_inserted = result.total_inserted + 1;
            } else {
                result.total_failed = result.total_failed + 1;
            }
