        let n1 = replication.replica_node_new("node_1", "localhost:8001");
        let n2 = replication.replica_node_new("node_2", "localhost:8002");

        group.node_add(n0);
        group.node_add(n1);
        group.node_add(n2);

        // 데이터 삽입 (정상 상태: 3/3 alive)
        let err1, ok1 = group.write_quorum("data_key", 42);
        print("Insert (3/3 alive): " + (if ok1 { "OK" } else { "FAIL" }));

        // 노드 1 장애 (2/3 alive, quorum=2 통과)
        group.nodes[1].state = replication.REPLICA_DEAD;
        let err2, ok2 = group.write_quorum("data_key_2", 100);
        print("Insert (2/3 alive): " + (if ok2 { "OK" } else { "FAIL" }));

        // 노드 2도 장애 (1/3 alive, quorum=2 실패)
        group.nodes[2].state = replication.REPLICA_DEAD;
        let err3, ok3 = group.write_quorum("data_key_3", 200);
        print("Insert (1/3 alive): " + (if ok3 { "OK" } else { "FAIL" }));

        // 노드 복구 (2/3 alive)
        group.nodes[1].state = replication.REPLICA_ALIVE;
        let err4, ok4 = group.write_quorum("data_key_4", 300);
        print("Insert (2/3 alive, recovered): " + (if ok4 { "OK" } else { "FAIL" }));
    }

