   386→
   387→    // === 헬퍼 함수 ===
   388→
   389→    @inline
   390→    func i32_to_string(n: i32) -> string {
   391→        if n == 0 { return "0"; }
   392→        if n == 1 { return "1"; }
   393→        if n < 0 { return "-" + i32_to_string(-n); }
   394→        return "?";
   395→    }
   396→
   397→    @inline
