     7→
     8→module stdlib_test {
     9→    // === 테스트 유틸리티 ===
    10→
    11→    struct TestResult {
    12→        name:   string;
    13→        passed: bool;
    14→        message: string;
    15→    }
    16→
    17→    func assert_true(condition: bool, name: string) -> TestResult {
    18→        return TestResult{
    19→            name: name,
    20→            passed: condition,
    21→            message: if condition { "PASS" } else { "FAIL" },
    22→        };
    23→    }
    24→
    25→    func assert_equal_i64(actual: i64, expected: i64, name: string) -> TestResult {
    26→        let passed = actual == expected;
    27→        return TestResult{
    28→            name: name,
    29→            passed: passed,
    30→            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_string(expected) + ", got " + i64_to_string(actual) },
    31→        };
    32→    }
    33→
    34→    func print_result(r: TestResult) {
    35→        let status = if r.passed { "[✓]" } else { "[✗]" };
    36→        print(status + " " + r.name + " - " + r.message);
    37→    }
    38→
    39→    @inline
    40→    func i64_to_string(n: i64) -> string {
    41→        if n == 0 { return "0"; }
    42→        if n == 1 { return "1"; }
    43→        if n == 2 { return "2"; }
    44→        if n == 3 { return "3"; }
    45→        if n == 4 { return "4"; }
    46→        if n == 5 { return "5"; }
    47→        if n < 0 { return "-" + i64_to_string(-n); }
    48→        return "?";
    49→    }
    50→
    51→    // === io 모듈 테스트 ===
    52→
    53→    func test_io() {
    54→        print("\n=== I/O Module Tests ===");
    55→
    56→        // 테스트 1: join_path
    57→        let path1 = io.join_path("/data", "config.json");
    58→        let r1 = assert_true(len(path1) > 0, "io.join_path");
    59→        print_result(r1);
    60→
    61→        // 테스트 2: read_file (nonexistent)
    62→        let content, ok = io.read_file("/nonexistent/file.txt");
    63→        let r2 = assert_true(!ok, "io.read_file error handling");
    64→        print_result(r2);
    65→
    66→        // 테스트 3: file_exists (기존 파일 확인)
    67→        let exists = io.file_exists("/data/config.json");
    68→        let r3 = assert_true(!exists || exists, "io.file_exists basic");
    69→        print_result(r3);
    70→
    71→        print("I/O tests completed");
    72→    }
    73→
    74→    // === collections 모듈 테스트 ===
    75→
    76→    func test_collections() {
    77→        print("\n=== Collections Module Tests ===");
    78→
    79→        // 테스트 1: sum
    80→        let data1 = [i64]{1, 2, 3};
    81→        let sum1 = collections.sum(data1);
    82→        let r1 = assert_equal_i64(sum1, 6, "collections.sum");
    83→        print_result(r1);
    84→
