    13→module data_insertion_test {
    14→    // === 테스트 상수 ===
    15→    const TEST_KEYS: i32 = 100;
    16→    const TEST_NODES: i32 = 3;
    17→
    18→    // === 테스트 유틸리티 ===
    19→
    20→    struct DataInsertionResult {
    21→        total_inserted:  i32;
    22→        total_failed:    i32;
    23→        total_reads:     i32;
    24→        successful_reads: i32;
    25→        avg_latency:     i32;
    26→    }
    27→
    28→    func result_new() -> DataInsertionResult {
    29→        return DataInsertionResult{
    30→            total_inserted:    0,
    31→            total_failed:      0,
    32→            total_reads:       0,
    33→            successful_reads:  0,
    34→            avg_latency:       0,
    35→        };
    36→    }
    37→
    38→    // === 데이터 생성 함수 ===
    39→
    40→    // 테스트 키 생성: "key_0", "key_1", ..., "key_99"
    41→    func make_test_key(idx: i32) -> string {
    42→        return "key_" + i32_to_str(idx);
    43→    }
    44→
    45→    // 테스트 값 생성: idx * 1000 + checksum
    46→    func make_test_value(idx: i32) -> i64 {
    47→        let checksum = i64(idx % 10);
    48→        return i64(idx) * 1000 + checksum;
    49→    }
    50→
    51→    // === 테스트 1: 기본 데이터 삽입 ===
    52→
    53→    func test_basic_insertion() {
    54→        print("\n=== Test 1: Basic Data Insertion ===");
    55→
    56→        // 단일 노드에 데이터 삽입
    57→        let node = distributed.dist_new("test_node", 1);
    58→
    59→        let result = result_new();
    60→        let i = 0;
    61→        for i = 0; i < TEST_KEYS; i = i + 1 {
    62→            let key = make_test_key(i);
    63→            let val = make_test_value(i);
    64→
    65→            // 쿼럼 쓰기 (현재 노드만 있으므로 quorum=1)
    66→            let node_copy = node;
    67→            node_copy.rep_group.nodes[0].state = replication.REPLICA_ALIVE;
    68→
    69→            let err, ok = node.rep_group.write_quorum(key, val);
    70→            if ok {
    71→                result.total_inserted = result.total_inserted + 1;
    72→            } else {
    73→                result.total_failed = result.total_failed + 1;
    74→            }
    75→        }
    76→
    77→        print("Inserted: " + i32_to_str(result.total_inserted) + " keys");
    78→        print("Failed: " + i32_to_str(result.total_failed) + " keys");
    79→        print("KV Store Count: " + i32_to_str(node.rep_group.nodes[0].store_count));
    80→    }
