    83→
    84→    func test_distributed_insertion() {
    85→        print("\n=== Test 2: Distributed Data Insertion (Round-Robin) ===");
    86→
    87→        // 3노드 클러스터 생성
    88→        let nodes = make([distributed.DistNode], TEST_NODES);
    89→        let i = 0;
    90→        for i = 0; i < TEST_NODES; i = i + 1 {
    91→            let node_id = "node_" + i32_to_str(i);
    92→            nodes[i] = distributed.dist_new(node_id, TEST_NODES);
    93→
    94→            // 해시 링에 노드 추가
    95→            nodes[i].ring.ring_add("node_0");
    96→            nodes[i].ring.ring_add("node_1");
    97→            nodes[i].ring.ring_add("node_2");
    98→
    99→            // 복제 그룹 초기화
   100→            let j = 0;
   101→            for j = 0; j < TEST_NODES; j = j + 1 {
   102→                let peer_node = replication.replica_node_new("node_" + i32_to_str(j), "localhost:" + i32_to_str(8000 + j));
   103→                nodes[i].rep_group.node_add(peer_node);
   104→            }
   105→
   106→            distributed.dist_register(&nodes[i]);
   107→        }
   108→
   109→        // 데이터 삽입 (라운드 로빈)
   110→        let result = result_new();
   111→        let k = 0;
   112→        for k = 0; k < TEST_KEYS; k = k + 1 {
   113→            let key = make_test_key(k);
   114→            let val = make_test_value(k);
   115→
   116→            // 라운드 로빈: k % 3 노드에 삽입
   117→            let node_idx = k % TEST_NODES;
   118→            let err, ok = nodes[node_idx].dist_put(key, val);
   119→
   120→            if ok && err == distributed.DIST_OK {
