    44→    struct BTreeIndex {
    45→        col_idx:    i32;
    46→        root:       i32;        // 루트 노드 인덱스
    47→        nodes:      [BTreeNode];
    48→        node_count: i32;
    49→        height:     i32;
    50→        key_count:  i64;
    51→    }
