   401→    @inline
   402→    func i32_to_str(n: i32) -> string {
   403→        if n == 0 { return "0"; }
   404→        if n == 1 { return "1"; }
   405→        if n == 2 { return "2"; }
   406→        if n == 3 { return "3"; }
   407→        if n == 4 { return "4"; }
   408→        if n == 5 { return "5"; }
   409→        if n == 6 { return "6"; }
   410→        if n == 7 { return "7"; }
   411→        if n == 8 { return "8"; }
   412→        if n == 9 { return "9"; }
   413→        if n < 0 { return "-" + i32_to_str(-n); }
   414→        let d = n / 10;
   415→        let r = n % 10;
   416→        return i32_to_str(d) + i32_to_str(r);
   417→    }
   418→
   419→    @inline
   420→    func i64_to_str(n: i64) -> string {
   421→        if n == 0 { return "0"; }
   422→        if n < 0 { return "-" + i64_to_str(-n); }
   423→        return i32_to_str(i32(n));
   424→    }
