// FreeLang Lock 모듈 - 행 수준 잠금 관리
// ============================================================================
// 목표: 다중 트랜잭션 환경에서 행 수준 잠금 (Row-Level Locking)
// 원리:
//   1. LockEntry: 행에 대한 잠금 기록 (row_id, tx_id, lock_type, timestamp)
//   2. SHARED 잠금: 여러 TX가 동시에 읽기 가능
//   3. EXCLUSIVE 잠금: 한 TX만 읽기/쓰기 가능
//   4. 호환성 검사: 요청된 잠금 타입과 기존 잠금의 충돌 판단
//   5. 업그레이드: SHARED → EXCLUSIVE 변환 (충돌 없을 때만)
// 구조:
//   - 상수 (잠금 타입, 에러 코드, 제한값)
//   - LockEntry, LockTable 구조체
//   - 공개 API (acquire, release, check, upgrade, stats)
//   - 내부 헬퍼 (slot 할당, 호환성 검사, 개수 계산)
// ============================================================================

module lock {
    // === 잠금 타입 ===
    const LOCK_SHARED:     i32 = 1;
    const LOCK_EXCLUSIVE:  i32 = 2;

    // === 에러 코드 ===
    const LOCK_OK:              i32 = 0;
    const LOCK_ERR_CONFLICT:    i32 = 75;
    const LOCK_ERR_FULL:        i32 = 76;
    const LOCK_ERR_NOT_FOUND:   i32 = 77;
    const LOCK_ERR_UPGRADE_FAIL: i32 = 78;

    // === 제한값 ===
    const MAX_LOCKS: i32 = 512;

    // === 데이터 구조체 ===

    // 잠금 엔트리
    struct LockEntry {
        row_id:     i64;    // 잠금 대상 행 ID
        tx_id:      i64;    // 잠금 소유 트랜잭션 ID
        lock_type:  i32;    // LOCK_SHARED 또는 LOCK_EXCLUSIVE
        acquired_ts: i64;   // 잠금 획득 타임스탬프
        is_used:    bool;   // 슬롯 사용 여부
    }

    // 잠금 테이블
    struct LockTable {
        entries:    [LockEntry];
        lock_count: i32;
    }

    // 전역 잠금 테이블
    let g_lock_table: LockTable = LockTable{
        entries:    make([LockEntry], MAX_LOCKS),
        lock_count: 0,
    };

    // === 공개 API ===

    // lock_init: 잠금 테이블 초기화
    func lock_init() -> i32 {
        g_lock_table.entries = make([LockEntry], MAX_LOCKS);
        g_lock_table.lock_count = 0;
        return LOCK_OK;
    }

    // lock_acquire: 행에 대한 잠금 획득
    // 호환성 검사:
    //   - 같은 TX가 이미 보유: 멱등 (기존 타입 유지)
    //   - EXCLUSIVE 요청 + 다른 TX 잠금: 충돌
    //   - SHARED 요청 + 다른 TX EXCLUSIVE: 충돌
    //   - SHARED + SHARED: OK
    func lock_acquire(lt: *LockTable, row_id: i64, tx_id: i64, lock_type: i32, ts: i64) -> i32 {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;
        let existing_type: i32 = 0;
        let has_existing: bool = false;

        // 같은 TX가 이미 보유한 잠금 확인
        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
                has_existing = true;
                existing_type = lt.entries[i].lock_type;
                break;
            }
            i = i + 1;
        }

        // 같은 TX가 이미 보유: 멱등 처리 (이미 있으면 LOCK_OK)
        if has_existing {
            return LOCK_OK;
        }

        // 호환성 검사: 다른 TX의 잠금 확인
        if lock_check_conflict(lt, row_id, tx_id, lock_type) {
            return LOCK_ERR_CONFLICT;
        }

        // 빈 슬롯 할당
        let slot: i32 = 0;
        let ok: bool = false;
        slot, ok = lt_alloc_slot(lt);
        if !ok {
            return LOCK_ERR_FULL;
        }

        // 잠금 기록
        lt.entries[slot] = LockEntry{
            row_id:     row_id,
            tx_id:      tx_id,
            lock_type:  lock_type,
            acquired_ts: ts,
            is_used:    true,
        };
        lt.lock_count = lt.lock_count + 1;

        return LOCK_OK;
    }

    // lock_release: 트랜잭션이 보유한 모든 잠금 해제
    func lock_release(lt: *LockTable, tx_id: i64) -> i32 {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;
        let released_count: i32 = 0;

        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].tx_id == tx_id {
                lt.entries[i].is_used = false;
                lt.lock_count = lt.lock_count - 1;
                released_count = released_count + 1;
            }
            i = i + 1;
        }

        return released_count;
    }

    // lock_check_conflict: 주어진 잠금 요청이 기존 잠금과 충돌하는지 확인
    // 충돌 조건:
    //   - 요청이 EXCLUSIVE인 경우: 같은 행의 다른 TX 잠금 모두 충돌
    //   - 요청이 SHARED이고, 기존이 EXCLUSIVE: 충돌
    //   - SHARED + SHARED: 충돌 없음
    func lock_check_conflict(lt: *LockTable, row_id: i64, tx_id: i64, lock_type: i32) -> bool {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id != tx_id {
                let existing_type: i32 = lt.entries[i].lock_type;

                // EXCLUSIVE 요청이면 다른 TX 잠금은 모두 충돌
                if lock_type == LOCK_EXCLUSIVE {
                    return true;
                }

                // SHARED 요청이고 기존이 EXCLUSIVE이면 충돌
                if lock_type == LOCK_SHARED && existing_type == LOCK_EXCLUSIVE {
                    return true;
                }

                // SHARED + SHARED는 충돌 없음 (계속 루프)
            }
            i = i + 1;
        }

        return false;
    }

    // lock_upgrade: SHARED 잠금을 EXCLUSIVE로 업그레이드
    // 조건: 같은 행의 다른 TX SHARED 잠금이 없어야 함
    func lock_upgrade(lt: *LockTable, row_id: i64, tx_id: i64) -> i32 {
        let existing_type: i32 = 0;
        let ok: bool = false;

        // 현재 잠금 타입 확인
        existing_type, ok = lock_get_type(lt, row_id, tx_id);
        if !ok {
            return LOCK_ERR_NOT_FOUND;
        }

        // 이미 EXCLUSIVE이면 업그레이드 실패
        if existing_type == LOCK_EXCLUSIVE {
            return LOCK_ERR_UPGRADE_FAIL;
        }

        // 다른 TX의 SHARED 잠금 개수 확인
        let other_shared_count: i32 = 0;
        other_shared_count = lt_count_shared_other(lt, row_id, tx_id);
        if other_shared_count > 0 {
            return LOCK_ERR_UPGRADE_FAIL;
        }

        // EXCLUSIVE로 변경
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;
        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
                lt.entries[i].lock_type = LOCK_EXCLUSIVE;
                return LOCK_OK;
            }
            i = i + 1;
        }

        return LOCK_ERR_NOT_FOUND;
    }

    // lock_get_type: 주어진 행의 TX 잠금 타입 조회
    func lock_get_type(lt: *LockTable, row_id: i64, tx_id: i64) -> (i32, bool) {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
                return (lt.entries[i].lock_type, true);
            }
            i = i + 1;
        }

        return (0, false);
    }

    // lock_stats: 잠금 테이블 통계
    func lock_stats(lt: *LockTable) -> string {
        let count_str: string = i64_to_string(i32_to_i64(lt.lock_count));
        let max_str: string = i64_to_string(i32_to_i64(MAX_LOCKS));
        return "LockTable: " + count_str + "/" + max_str;
    }

    // === 내부 헬퍼 함수 ===

    // lt_alloc_slot: 빈 슬롯 할당
    func lt_alloc_slot(lt: *LockTable) -> (i32, bool) {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if !lt.entries[i].is_used {
                return (i, true);
            }
            i = i + 1;
        }

        return (-1, false);
    }

    // lt_has_lock: 주어진 행에 TX가 보유한 잠금이 있는지 확인
    @inline
    func lt_has_lock(lt: *LockTable, row_id: i64, tx_id: i64) -> (i32, bool) {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if lt.entries[i].is_used && lt.entries[i].row_id == row_id && lt.entries[i].tx_id == tx_id {
                return (lt.entries[i].lock_type, true);
            }
            i = i + 1;
        }

        return (0, false);
    }

    // lt_has_exclusive_other: 주어진 행에 다른 TX의 EXCLUSIVE 잠금이 있는지 확인
    @inline
    func lt_has_exclusive_other(lt: *LockTable, row_id: i64, tx_id: i64) -> bool {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if lt.entries[i].is_used &&
               lt.entries[i].row_id == row_id &&
               lt.entries[i].tx_id != tx_id &&
               lt.entries[i].lock_type == LOCK_EXCLUSIVE {
                return true;
            }
            i = i + 1;
        }

        return false;
    }

    // lt_has_any_other: 주어진 행에 다른 TX의 잠금이 있는지 확인
    @inline
    func lt_has_any_other(lt: *LockTable, row_id: i64, tx_id: i64) -> bool {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;

        while i < max_i {
            if lt.entries[i].is_used &&
               lt.entries[i].row_id == row_id &&
               lt.entries[i].tx_id != tx_id {
                return true;
            }
            i = i + 1;
        }

        return false;
    }

    // lt_count_shared_other: 주어진 행의 다른 TX SHARED 잠금 개수
    func lt_count_shared_other(lt: *LockTable, row_id: i64, tx_id: i64) -> i32 {
        let i: i32 = 0;
        let max_i: i32 = MAX_LOCKS;
        let count: i32 = 0;

        while i < max_i {
            if lt.entries[i].is_used &&
               lt.entries[i].row_id == row_id &&
               lt.entries[i].tx_id != tx_id &&
               lt.entries[i].lock_type == LOCK_SHARED {
                count = count + 1;
            }
            i = i + 1;
        }

        return count;
    }

    // === 숫자 변환 헬퍼 ===

    // i32_to_i64: i32를 i64로 변환
    @inline
    func i32_to_i64(val: i32) -> i64 {
        return val as i64;
    }

    // i64_to_string: i64를 문자열로 변환
    func i64_to_string(val: i64) -> string {
        if val == 0 {
            return "0";
        }

        let negative: bool = val < 0;
        let abs_val: i64 = val;
        if negative {
            abs_val = 0 - val;
        }

        let result: string = "";
        while abs_val > 0 {
            let digit: i64 = abs_val % 10;
            let digit_char: string = i64_digit_to_char(digit);
            result = digit_char + result;
            abs_val = abs_val / 10;
        }

        if negative {
            result = "-" + result;
        }

        return result;
    }

    // i64_digit_to_char: 0-9의 i64를 문자로 변환
    @inline
    func i64_digit_to_char(digit: i64) -> string {
        if digit == 0 { return "0"; }
        if digit == 1 { return "1"; }
        if digit == 2 { return "2"; }
        if digit == 3 { return "3"; }
        if digit == 4 { return "4"; }
        if digit == 5 { return "5"; }
        if digit == 6 { return "6"; }
        if digit == 7 { return "7"; }
        if digit == 8 { return "8"; }
        if digit == 9 { return "9"; }
        return "";
    }
}
