const IR_LOAD_COL:  i32 = 3;
const IR_STORE_COL: i32 = 4;
const IR_ADD:       i32 = 5;
const IR_SUB:       i32 = 6;
const IR_MUL:       i32 = 7;
const IR_DIV:       i32 = 8;
const IR_CMP:       i32 = 9;
const IR_JMP:       i32 = 10;
const IR_JZ:        i32 = 11;
const IR_JNZ:       i32 = 12;
const IR_CALL:      i32 = 13;
const IR_RET:       i32 = 14;
const IR_LABEL:     i32 = 15;
const IR_MOV:       i32 = 16;
const IR_PUSH:      i32 = 17;
const IR_POP:       i32 = 18;
const IR_NOP:       i32 = 19;
const IR_NEXT_ROW:  i32 = 20;
const IR_AGGREGATE: i32 = 21;

const IR_OK:             i32 = 0;
const IR_ERR_FULL:       i32 = 100;
const IR_ERR_INVALID_OP: i32 = 101;

const MAX_IR_OPS:    i32 = 256;
const MAX_TEMP_REGS: i32 = 64;
```

### 구조체
```fl
struct IRInstruction {
    opcode:    i32;
    dst_reg:   i32;
    src1_reg:  i32;
    src2_reg:  i32;
    imm_int:   i64;
    imm_str:   string;
    label_id:  i32;
    func_name: string;
}

struct IRBuilder {
    instructions:  [IRInstruction];   // MAX_IR_OPS=256
    instr_count:   i32;
    next_temp_reg: i32;
    next_label_id: i32;
}
```

