    35→        let status = if r.passed { "[✓]" } else { "[✗]" };
    36→        print(status + " " + r.name + " - " + r.message);
    37→    }
    38→
    39→    @inline
    40→    func i64_to_string(n: i64) -> string {
    41→        if n == 0 { return "0"; }
    42→        if n == 1 { return "1"; }
    43→        if n == 2 { return "2"; }
    44→        if n == 3 { return "3"; }
    45→        if n == 4 { return "4"; }
    46→        if n == 5 { return "5"; }
    47→        if n < 0 { return "-" + i64_to_string(-n); }
    48→        return "?";
    49→    }
