   319→    // === 파이프라인 검증 함수 ===
   320→
   321→    // 물리 계획의 파이프라인이 유효한지 검증
   322→    func physical_plan_validate(pp: *PhysicalPlan) -> bool {
   323→        if pp.root_op_idx < 0 {
   324→            return false;
   325→        }
   326→
   327→        if pp.root_op_idx >= MAX_OPS || !pp.ops[pp.root_op_idx].is_used {
   328→            return false;
   329→        }
   330→
   331→        // 사이클 감지: 파이프라인 순회 (최대 MAX_OPS번)
   332→        let op_idx = pp.root_op_idx;
   333→        let visited = 0;
   334→
   335→        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
   336→            if op_idx >= MAX_OPS {
   337→                return false;
   338→            }
   339→
   340→            if !pp.ops[op_idx].is_used {
   341→                return false;
   342→            }
   343→
   344→            op_idx = pp.ops[op_idx].next_op;
   345→        }
   346→
   347→        // 순환 그래프 감지 (MAX_OPS 이상 순회)
   348→        if op_idx >= 0 {
   349→            return false;
   350→        }
   351→
   352→        return true;
   353→    }
   354→
   355→    // === 연산자 통계 ===
   356→
   357→    // 파이프라인의 연산자 깊이(길이) 반환
   358→    func physical_plan_depth(pp: *PhysicalPlan) -> i32 {
   359→        if pp.root_op_idx < 0 {
   360→            return 0;
   361→        }
   362→
   363→        let op_idx = pp.root_op_idx;
   364→        let depth = 0;
   365→
   366→        for depth = 0; depth < MAX_OPS && op_idx >= 0; depth = depth + 1 {
   367→            op_idx = pp.ops[op_idx].next_op;
   368→        }
   369→
   370→        return depth;
   371→    }
   372→
   373→    // 파이프라인에서 특정 연산자 타입이 포함되어 있는지 확인
   374→    func physical_plan_has_op_type(pp: *PhysicalPlan, op_type: i32) -> bool {
   375→        let op_idx = pp.root_op_idx;
   376→        let visited = 0;
   377→
   378→        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
   379→            if pp.ops[op_idx].op_type == op_type {
   380→                return true;
   381→            }
   382→
   383→            op_idx = pp.ops[op_idx].next_op;
   384→        }
   385→
   386→        return false;
   387→    }
