   390→
   391→    // 전체 파이프라인 상세 정보 출력
   392→    func physical_plan_print_pipeline(pp: *PhysicalPlan) -> string {
   393→        let result = "Pipeline: ";
   394→
   395→        if pp.root_op_idx < 0 {
   396→            result = result + "(empty)";
   397→            return result;
   398→        }
   399→
   400→        let op_idx = pp.root_op_idx;
   401→        let visited = 0;
   402→
   403→        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
   404→            let op = pp.ops[op_idx];
   405→            result = result + op_type_to_str(op.op_type);
   406→
   407→            if op.next_op >= 0 {
