     2→// FreeLang ResultSet 모듈 - 쿼리 결과 저장 및 반환
     3→// ============================================================================
     4→// 목표: 쿼리 엔진에서 반환된 행들을 효율적으로 저장 및 관리
     5→// 원리:
     6→//   1. SoA 레이아웃: int_vals / str_vals / bool_vals 배열 분리 저장
     7→//   2. 유연한 컬럼 수: col_count로 사용할 컬럼 수 지정
     8→//   3. 에러 처리: has_error, error_code로 상태 관리
     9→//   4. 타입별 접근: get_int / get_str / get_bool로 타입 안전 조회
    10→// 구조:
    11→//   - 상수 정의 (에러 코드, 제한값)
    12→//   - ResultRow, ResultSet 구조체
    13→//   - 기본 관리 함수 (new, clear)
    14→//   - 행 추가 함수 (add_row_from_schema)
    15→//   - 행 조회 함수 (get_row, get_int, get_str, get_bool)
    16→//   - 메타데이터 함수 (get_row_count, get_col_count)
    17→//   - 디버그 함수 (to_string)
    18→// ============================================================================
    19→
    20→module result_set {
    21→    // === 상수 (에러 코드) ===
    22→    const RESULT_OK:        i32 = 0;
    23→    const RESULT_ERR_FULL:  i32 = 140;
    24→    const RESULT_ERR_EMPTY: i32 = 141;
    25→
    26→    // === 제한값 ===
    27→    const MAX_RESULT_ROWS: i32 = 1024;
    28→    const MAX_RESULT_COLS: i32 = 16;
    29→
    30→    // === 데이터 구조체 ===
    31→
    32→    // 결과 행 (SoA 레이아웃)
    33→    struct ResultRow {
    34→        int_vals:  [i64];
    35→        str_vals:  [string];
    36→        bool_vals: [bool];
    37→        col_count: i32;
    38→    }
    39→
    40→    // 결과 집합
    41→    struct ResultSet {
    42→        rows:       [ResultRow];
    43→        row_count:  i32;
    44→        col_count:  i32;
    45→        has_error:  bool;
    46→        error_code: i32;
    47→    }
    48→
    49→    // === 생성 및 초기화 함수 ===
    50→
    51→    // ResultSet 생성
    52→    // col_count: 결과에 포함될 컬럼 수 (MAX_RESULT_COLS 이하)
    53→    func result_set_new(col_count: i32) -> ResultSet {
    54→        if col_count < 0 || col_count > MAX_RESULT_COLS {
    55→            return ResultSet{
    56→                rows:       make([ResultRow], 0),
    57→                row_count:  0,
    58→                col_count:  0,
    59→                has_error:  true,
    60→                error_code: RESULT_ERR_EMPTY,
    61→            };
    62→        }
    63→
    64→        return ResultSet{
    65→            rows:       make([ResultRow], MAX_RESULT_ROWS),
    66→            row_count:  0,
    67→            col_count:  col_count,
    68→            has_error:  false,
    69→            error_code: RESULT_OK,
    70→        };
    71→    }
    72→
    73→    // ResultSet 초기화 (모든 행 제거)
    74→    func (rs: *ResultSet) result_set_clear() -> i32 {
    75→        // 기존 행들을 초기화
    76→        let i = 0;
    77→        for i = 0; i < rs.row_count; i = i + 1 {
    78→            rs.rows[i] = ResultRow{
    79→                int_vals:  make([i64], 0),
    80→                str_vals:  make([string], 0),
    81→                bool_vals: make([bool], 0),
    82→                col_count: 0,
    83→            };
    84→        }
    85→        rs.row_count = 0;
    86→        rs.has_error = false;
    87→        rs.error_code = RESULT_OK;
    88→        return RESULT_OK;
    89→    }
    90→
    91→    // === 행 추가 함수 ===
    92→
    93→    // 스키마를 기반으로 테이블의 특정 행을 결과 집합에 추가
    94→    // row_idx: 테이블의 행 인덱스
    95→    func (rs: *ResultSet) result_set_add_row_from_schema(t: schema.Table, row_idx: i32) -> i32 {
    96→        // 용량 초과 확인
    97→        if rs.row_count >= MAX_RESULT_ROWS {
    98→            rs.has_error = true;
    99→            rs.error_code = RESULT_ERR_FULL;
   100→            return RESULT_ERR_FULL;
   101→        }
   102→
   103→        // 행 인덱스 범위 확인
   104→        if row_idx < 0 || row_idx >= t.row_count {
   105→            return RESULT_ERR_EMPTY;
   106→        }
   107→
   108→        // 테이블에서 행 추출
   109→        let record = t.table_get_row(row_idx);
   110→
   111→        // ResultRow 생성
   112→        let new_row = ResultRow{
   113→            int_vals:  make([i64],    MAX_RESULT_COLS),
   114→            str_vals:  make([string], MAX_RESULT_COLS),
   115→            bool_vals: make([bool],   MAX_RESULT_COLS),
   116→            col_count: rs.col_count,
   117→        };
   118→
   119→        // 각 컬럼 타입별로 값 복사
   120→        let int_idx = 0;
   121→        let str_idx = 0;
   122→        let bool_idx = 0;
   123→        let col_idx = 0;
   124→
   125→        for col_idx = 0; col_idx < t.schema.col_count; col_idx = col_idx + 1 {
   126→            if col_idx >= rs.col_count {
   127→                break;
   128→            }
   129→
   130→            let col_def = t.schema.col_defs[col_idx];
   131→
   132→            if col_def.col_type == schema.COL_TYPE_INT {
   133→                new_row.int_vals[int_idx] = record.int_vals[int_idx];
   134→                int_idx = int_idx + 1;
   135→            }
   136→
   137→            if col_def.col_type == schema.COL_TYPE_STR {
   138→                new_row.str_vals[str_idx] = record.str_vals[str_idx];
   139→                str_idx = str_idx + 1;
   140→            }
   141→
   142→            if col_def.col_type == schema.COL_TYPE_BOOL {
   143→                new_row.bool_vals[bool_idx] = record.bool_vals[bool_idx];
   144→                bool_idx = bool_idx + 1;
   145→            }
   146→        }
   147→
   148→        // ResultSet에 행 추가
   149→        rs.rows[rs.row_count] = new_row;
   150→        rs.row_count = rs.row_count + 1;
   151→
   152→        return RESULT_OK;
   153→    }
   154→
   155→    // === 행 조회 함수 ===
   156→
   157→    // 결과 집합에서 특정 행 조회
   158→    func (rs: *ResultSet) result_set_get_row(idx: i32) -> (ResultRow, i32) {
   159→        // 범위 확인
   160→        if idx < 0 || idx >= rs.row_count {
   161→            let empty_row = ResultRow{
   162→                int_vals:  make([i64], 0),
   163→                str_vals:  make([string], 0),
   164→                bool_vals: make([bool], 0),
   165→                col_count: 0,
   166→            };
   167→            return (empty_row, RESULT_ERR_EMPTY);
   168→        }
   169→
   170→        return (rs.rows[idx], RESULT_OK);
   171→    }
   172→
   173→    // 결과 집합에서 특정 행의 정수 값 조회
   174→    func (rs: *ResultSet) result_set_get_int(row_idx: i32, col_idx: i32) -> (i64, i32) {
   175→        // 행 범위 확인
   176→        if row_idx < 0 || row_idx >= rs.row_count {
   177→            return (0, RESULT_ERR_EMPTY);
   178→        }
   179→
   180→        let row = rs.rows[row_idx];
   181→
   182→        // 컬럼 범위 확인
   183→        if col_idx < 0 || col_idx >= row.col_count {
   184→            return (0, RESULT_ERR_EMPTY);
   185→        }
   186→
   187→        // int_vals 배열에서 값 추출
   188→        if col_idx < MAX_RESULT_COLS {
   189→            return (row.int_vals[col_idx], RESULT_OK);
   190→        }
   191→
   192→        return (0, RESULT_ERR_EMPTY);
   193→    }
   194→
   195→    // 결과 집합에서 특정 행의 문자열 값 조회
   196→    func (rs: *ResultSet) result_set_get_str(row_idx: i32, col_idx: i32) -> (string, i32) {
   197→        // 행 범위 확인
   198→        if row_idx < 0 || row_idx >= rs.row_count {
   199→            return ("", RESULT_ERR_EMPTY);
   200→        }
   201→
   202→        let row = rs.rows[row_idx];
   203→
   204→        // 컬럼 범위 확인
   205→        if col_idx < 0 || col_idx >= row.col_count {
   206→            return ("", RESULT_ERR_EMPTY);
   207→        }
   208→
   209→        // str_vals 배열에서 값 추출
   210→        if col_idx < MAX_RESULT_COLS {
   211→            return (row.str_vals[col_idx], RESULT_OK);
   212→        }
   213→
   214→        return ("", RESULT_ERR_EMPTY);
   215→    }
   216→
   217→    // === 메타데이터 함수 ===
   218→
   219→    // 결과 집합의 행 개수 반환
   220→    func (rs: *ResultSet) result_set_get_row_count() -> i32 {
   221→        return rs.row_count;
   222→    }
   223→
   224→    // 결과 집합의 컬럼 개수 반환
   225→    func (rs: *ResultSet) result_set_get_col_count() -> i32 {
   226→        return rs.col_count;
   227→    }
   228→
   229→    // === 디버그 및 출력 함수 ===
   230→
   231→    // ResultSet을 문자열로 변환 (디버깅용)
   232→    // 형식: "Row 0: [val1, val2, ...]\nRow 1: ..."
   233→    func (rs: *ResultSet) result_set_to_string() -> string {
   234→        if rs.row_count == 0 {
   235→            return "[Empty ResultSet]";
   236→        }
   237→
   238→        let output = "";
   239→        let i = 0;
   240→
   241→        for i = 0; i < rs.row_count; i = i + 1 {
   242→            let row = rs.rows[i];
   243→
   244→            // "Row i: ["
   245→            output = output + "Row " + i32_to_str(i) + ": [";
   246→
   247→            // 각 컬럼값 추가 (첫 5개만 표시하는 제약)
   248→            let j = 0;
   249→            for j = 0; j < row.col_count; j = j + 1 {
   250→                if j > 0 {
   251→                    output = output + ", ";
   252→                }
   253→
   254→                // int_vals에서 값 출력
   255→                if j < MAX_RESULT_COLS {
   256→                    let val = row.int_vals[j];
   257→                    output = output + i64_to_str(val);
   258→                }
   259→            }
   260→
   261→            output = output + "]\n";
   262→        }
   263→
   264→        return output;
   265→    }
   266→
   267→    // === 헬퍼 함수 ===
   268→
   269→    // i32를 문자열로 변환
   270→    @inline
   271→    func i32_to_str(n: i32) -> string {
   272→        if n == 0 { return "0"; }
   273→        if n == 1 { return "1"; }
   274→        if n == 2 { return "2"; }
   275→        if n == 3 { return "3"; }
   276→        if n == 4 { return "4"; }
   277→        if n == 5 { return "5"; }
   278→        if n == 6 { return "6"; }
   279→        if n == 7 { return "7"; }
   280→        if n == 8 { return "8"; }
   281→        if n == 9 { return "9"; }
   282→        if n < 0 { return "-" + i32_to_str(-n); }
   283→        let d = n / 10;
   284→        let r = n % 10;
   285→        return i32_to_str(d) + i32_to_str(r);
   286→    }
   287→
   288→    // i64를 문자열로 변환
   289→    @inline
   290→    func i64_to_str(n: i64) -> string {
   291→        if n == 0 { return "0"; }
   292→        if n < 0 { return "-" + i64_to_str(-n); }
   293→        return i32_to_str(i32(n));
   294→    }
   295→}
