   301→    // 集計タイプを文字列に変換 (デバッグ用)
   302→    @inline
   303→    func agg_type_to_str(agg_type: i32) -> string {
   304→        if agg_type == PHYS_AGG_COUNT {
   305→            return "COUNT";
   306→        }
   307→        if agg_type == PHYS_AGG_SUM {
   308→            return "SUM";
   309→        }
   310→        if agg_type == PHYS_AGG_MAX {
   311→            return "MAX";
   312→        }
   313→        if agg_type == PHYS_AGG_MIN {
   314→            return "MIN";
   315→        }
   316→        return "NONE";
   317→    }
   318→
   319→    // === 파이프라인 검증 함수 ===
   320→
   321→    // 물리 계획의 파이프라인이 유효한지 검증
   322→    func physical_plan_validate(pp: *PhysicalPlan) -> bool {
   323→        if pp.root_op_idx < 0 {
   324→            return false;
   325→        }
   326→
   327→        if pp.root_op_idx >= MAX_OPS || !pp.ops[pp.root_op_idx].is_used {
   328→            return false;
   329→        }
   330→
   331→        // 사이클 감지: 파이프라인 순회 (최대 MAX_OPS번)
   332→        let op_idx = pp.root_op_idx;
   333→        let visited = 0;
   334→
   335→        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
   336→            if op_idx >= MAX_OPS {
   337→                return false;
   338→            }
   339→
   340→            if !pp.ops[op_idx].is_used {
   341→                return false;
   342→            }
   343→
   344→            op_idx = pp.ops[op_idx].next_op;
   345→        }
   346→
   347→        // 순환 그래프 감지 (MAX_OPS 이상 순회)
   348→        if op_idx >= 0 {
   349→            return false;
   350→        }
   351→
   352→        return true;
   353→    }
   354→
