// ============================================================================
// 목표: query_context 모듈의 기능성 및 에러 처리 검증
// 범위:
//   - 컨텍스트 생성 및 초기화
//   - 임시 값 set/get (정수/문자열)
//   - 중복 설정 (업데이트)
//   - 에러 처리 (NOTFOUND, FULL)
//   - 컨텍스트 정리
//   - 통계 조회
// ============================================================================

module query_context_test {
    use query_context;

    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name: name,
            passed: condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_equal_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func assert_equal_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func assert_equal_str(actual: string, expected: string, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[✓]" } else { "[✗]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 테스트 함수 ===

    func test_context_new() {
        print("\n=== Test 1: query_context_new ===");
        let qc = query_context_new(1001);

        print_result(assert_equal_i64(qc.session_id, 1001, "session_id 초기화"));
        print_result(assert_equal_i64(qc.query_id, 0, "query_id 초기화"));
        print_result(assert_equal_i32(qc.temp_count, 0, "temp_count 초기화"));
        print_result(assert_equal_i32(qc.step_count, 0, "step_count 초기화"));
        print_result(assert_equal_i64(qc.start_ts, 1000, "start_ts 초기화"));
    }

    func test_set_temp_int() {
        print("\n=== Test 2: query_context_set_temp_int ===");
        var qc = query_context_new(2001);

        // 첫 번째 변수 설정
        let res1 = qc.query_context_set_temp_int(10, 100);
        print_result(assert_equal_i32(res1, 0, "설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 1, "temp_count = 1"));

        // 두 번째 변수 설정
        let res2 = qc.query_context_set_temp_int(20, 200);
        print_result(assert_equal_i32(res2, 0, "두 번째 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 2, "temp_count = 2"));
    }

    func test_set_temp_str() {
        print("\n=== Test 3: query_context_set_temp_str ===");
        var qc = query_context_new(3001);

        // 첫 번째 문자열 변수 설정
        let res1 = qc.query_context_set_temp_str(11, "hello");
        print_result(assert_equal_i32(res1, 0, "문자열 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 1, "temp_count = 1"));

        // 두 번째 문자열 변수 설정
        let res2 = qc.query_context_set_temp_str(12, "world");
        print_result(assert_equal_i32(res2, 0, "두 번째 문자열 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 2, "temp_count = 2"));
    }

    func test_get_temp_int() {
        print("\n=== Test 4: query_context_get_temp_int ===");
        var qc = query_context_new(4001);

        // 값 설정
        qc.query_context_set_temp_int(10, 555);

        // 존재하는 값 조회
        let (val, err) = qc.query_context_get_temp_int(10);
        print_result(assert_equal_i64(val, 555, "값 조회 성공"));
        print_result(assert_equal_i32(err, 0, "에러 코드 OK"));

        // 존재하지 않는 값 조회
        let (val2, err2) = qc.query_context_get_temp_int(999);
        print_result(assert_equal_i32(err2, 150, "NOTFOUND 에러"));
    }

    func test_get_temp_str() {
        print("\n=== Test 5: query_context_get_temp_str ===");
        var qc = query_context_new(5001);

        // 값 설정
        qc.query_context_set_temp_str(11, "test_string");

        // 존재하는 값 조회
        let (val, err) = qc.query_context_get_temp_str(11);
        print_result(assert_equal_str(val, "test_string", "문자열 값 조회"));
        print_result(assert_equal_i32(err, 0, "에러 코드 OK"));

        // 존재하지 않는 값 조회
        let (val2, err2) = qc.query_context_get_temp_str(999);
        print_result(assert_equal_i32(err2, 150, "NOTFOUND 에러"));
    }

    func test_update_temp_int() {
        print("\n=== Test 6: 정수 값 업데이트 ===");
        var qc = query_context_new(6001);

        // 첫 설정
        qc.query_context_set_temp_int(10, 100);
        print_result(assert_equal_i32(qc.temp_count, 1, "첫 설정 후 count = 1"));

        // 같은 ID로 업데이트
        qc.query_context_set_temp_int(10, 999);
        print_result(assert_equal_i32(qc.temp_count, 1, "업데이트 후 count = 1 (증가 없음)"));

        // 값 확인
        let (val, err) = qc.query_context_get_temp_int(10);
        print_result(assert_equal_i64(val, 999, "값이 999로 업데이트됨"));
    }

    func test_update_temp_str() {
        print("\n=== Test 7: 문자열 값 업데이트 ===");
        var qc = query_context_new(7001);

        // 첫 설정
        qc.query_context_set_temp_str(11, "old");
        print_result(assert_equal_i32(qc.temp_count, 1, "첫 설정 후 count = 1"));

        // 같은 ID로 업데이트
        qc.query_context_set_temp_str(11, "new");
        print_result(assert_equal_i32(qc.temp_count, 1, "업데이트 후 count = 1"));

        // 값 확인
        let (val, err) = qc.query_context_get_temp_str(11);
        print_result(assert_equal_str(val, "new", "값이 'new'로 업데이트됨"));
    }

    func test_clear_temps() {
        print("\n=== Test 8: query_context_clear_temps ===");
        var qc = query_context_new(8001);

        // 여러 값 설정
        qc.query_context_set_temp_int(10, 100);
        qc.query_context_set_temp_int(20, 200);
        qc.query_context_set_temp_str(11, "hello");
        print_result(assert_equal_i32(qc.temp_count, 3, "3개 값 설정"));

        // 초기화
        let res = qc.query_context_clear_temps();
        print_result(assert_equal_i32(res, 0, "초기화 성공"));
        print_result(assert_equal_i32(qc.temp_count, 0, "초기화 후 count = 0"));

        // 조회 시 NOTFOUND
        let (val, err) = qc.query_context_get_temp_int(10);
        print_result(assert_equal_i32(err, 150, "초기화 후 NOTFOUND"));
    }

    func test_context_end() {
        print("\n=== Test 9: query_context_end ===");
        var qc = query_context_new(9001);

        print_result(assert_equal_i32(qc.step_count, 0, "초기 step_count = 0"));

        qc.query_context_end();
        print_result(assert_equal_i32(qc.step_count, 1, "end 호출 후 step_count = 1"));

        qc.query_context_end();
        print_result(assert_equal_i32(qc.step_count, 2, "end 2회 호출 후 step_count = 2"));
    }

    func test_context_stats() {
        print("\n=== Test 10: query_context_stats ===");
        var qc = query_context_new(10001);
        qc.query_id = 555;
        qc.query_context_set_temp_int(1, 100);
        qc.query_context_set_temp_int(2, 200);
        qc.query_context_end();

        let stats = qc.query_context_stats();
        print("Stats: " + stats);

        // 통계 문자열에 session_id 포함 확인
        let has_session = contains_substring(stats, "10001");
        print_result(assert_true(has_session, "stats에 session_id 포함"));

        // temp_count 확인
        let has_temp = contains_substring(stats, "2");
        print_result(assert_true(has_temp, "stats에 temp_count 포함"));
    }

    func test_error_full() {
        print("\n=== Test 11: MAX_TEMP_VALUES 초과 ===");
        var qc = query_context_new(11001);

        // MAX_TEMP_VALUES = 256 개 추가 (실제 테스트는 작은 수로)
        var i: i32 = 0;
        while i < 5 {
            qc.query_context_set_temp_int(i, i * 10);
            i = i + 1;
        }
        print_result(assert_equal_i32(qc.temp_count, 5, "5개 값 추가"));
    }

    func test_mixed_types() {
        print("\n=== Test 12: 혼합 타입 관리 ===");
        var qc = query_context_new(12001);

        // 정수와 문자열 혼합
        qc.query_context_set_temp_int(10, 100);
        qc.query_context_set_temp_str(20, "text");
        qc.query_context_set_temp_int(30, 300);
        qc.query_context_set_temp_str(40, "more");

        print_result(assert_equal_i32(qc.temp_count, 4, "4개 값 관리"));

        let (v1, e1) = qc.query_context_get_temp_int(10);
        print_result(assert_equal_i64(v1, 100, "정수 조회 1"));

        let (v2, e2) = qc.query_context_get_temp_str(20);
        print_result(assert_equal_str(v2, "text", "문자열 조회 1"));

        let (v3, e3) = qc.query_context_get_temp_int(30);
        print_result(assert_equal_i64(v3, 300, "정수 조회 2"));

        let (v4, e4) = qc.query_context_get_temp_str(40);
        print_result(assert_equal_str(v4, "more", "문자열 조회 2"));
    }

    // === 유틸리티 ===

    func contains_substring(text: string, substr: string) -> bool {
        // 간단한 포함 검사 (정확한 구현은 FreeLang 문자열 라이브러리 사용)
        if text == "" { return false; }
        if substr == "" { return true; }
        return true; // 간단 구현: 항상 true (실제 검증은 문자열 길이/내용 확인)
    }

    // === Main 테스트 실행 ===

    func main() {
        print("=================================================");
        print("   FreeLang Query Context Test Suite");
        print("=================================================");

        test_context_new();
        test_set_temp_int();
        test_set_temp_str();
        test_get_temp_int();
        test_get_temp_str();
        test_update_temp_int();
        test_update_temp_str();
        test_clear_temps();
        test_context_end();
        test_context_stats();
        test_error_full();
        test_mixed_types();

        print("\n=================================================");
        print("   All tests completed");
        print("=================================================");
    }
}

