        // 테이블 생성
        let t = schema.table_new(s);

        // 행 삽입
        let row = schema.record_new();
        row.int_vals[0] = 1;
        row.str_vals[0] = "Alice";
        row.bool_vals[0] = true;
        let id, ok = t.table_insert(row);
