    // === Test 7: MAX_RESULT_ROWS 초과 ===
    func test_max_rows_exceeded() -> bool {
        let s = schema.schema_new("test");
        s.schema_add_col("id", schema.COL_TYPE_INT, false);
        let t = schema.table_new(s);

        // 많은 행 삽입
        let i = 0;
        for i = 0; i < result_set.MAX_RESULT_ROWS; i = i + 1 {
            let row = schema.record_new();
            row.int_vals[0] = i64(i);
            t.table_insert(row);
        }

        // ResultSet 생성
        let rs = result_set.result_set_new(1);

        // MAX_RESULT_ROWS까지는 추가 가능
        let j = 0;
        for j = 0; j < result_set.MAX_RESULT_ROWS; j = j + 1 {
            let err = rs.result_set_add_row_from_schema(t, j);
            if err != result_set.RESULT_OK {
                return false;
            }
        }

        if rs.row_count != result_set.MAX_RESULT_ROWS {
            return false;
        }

        // 하나 더 추가하면 오류
        let row_extra = schema.record_new();
        row_extra.int_vals[0] = 9999;
        t.table_insert(row_extra);

        let err_extra = rs.result_set_add_row_from_schema(t, result_set.MAX_RESULT_ROWS);
        if err_extra != result_set.RESULT_ERR_FULL {
            return false;
        }
        if !rs.has_error {
            return false;
        }

        return true;
    }

