   369→    @inline
   370→    func i32_to_str(n: i32) -> string {
   371→        if n == 0 { return "0"; }
   372→        if n == 1 { return "1"; }
   373→        if n == 2 { return "2"; }
   374→        if n == 3 { return "3"; }
   375→        if n == 4 { return "4"; }
   376→        if n == 5 { return "5"; }
   377→        if n == 6 { return "6"; }
   378→        if n == 7 { return "7"; }
   379→        if n == 8 { return "8"; }
   380→        if n == 9 { return "9"; }
   381→        if n < 0 { return "-" + i32_to_str(-n); }
   382→        let d = n / 10;
   383→        let r = n % 10;
   384→        return i32_to_str(d) + i32_to_str(r);
   385→    }
