    38→        col_type: i32;
    39→        nullable: bool;
    40→    }
    41→
    42→    // 테이블 스키마 (DDL)
    43→    struct TableSchema {
    44→        name:        string;
    45→        col_defs:    [ColumnDef];
    46→        col_count:   i32;
    47→        primary_key: i32;    // 기본키 컬럼 인덱스 (0 = 첫 번째)
