// ============================================================================
// FreeLang QuerySession 모듈 테스트
// ============================================================================
// 테스트 항목:
//   1. query_session_new: 세션 생성 확인
//   2. query_session_execute: 쿼리 실행 및 히스토리 기록
//   3. query_session_get_history: 히스토리 조회
//   4. query_session_get_total: 전체 쿼리 수
//   5. query_session_last_query: 마지막 쿼리
//   6. query_session_clear_history: 히스토리 초기화
//   7. query_session_stats: 통계 문자열 생성
//   8. 에러 처리: QSESS_ERR_FULL, QSESS_ERR_NOTFOUND
// ============================================================================

module test_query_session {
    // === 헬퍼 함수 ===

    func assert_eq(actual: i32, expected: i32, msg: string) -> bool {
        if actual == expected {
            return true;
        }
        println("FAIL: " + msg + " (expected: " + i32_to_str(expected) + ", got: " + i32_to_str(actual) + ")");
        return false;
    }

    func assert_str_eq(actual: string, expected: string, msg: string) -> bool {
        if actual == expected {
            return true;
        }
        println("FAIL: " + msg + " (expected: " + expected + ", got: " + actual + ")");
        return false;
    }

    func assert_bool(condition: bool, msg: string) -> bool {
        if condition {
            return true;
        }
        println("FAIL: " + msg);
        return false;
    }

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    // === 테스트 함수 ===

    // Test 1: 세션 생성
    func test_session_new() -> bool {
        println("Test 1: query_session_new");
        let sess = query_session.query_session_new(1001);

        if !assert_eq(sess.session_id, 1001, "session_id should be 1001") {
            return false;
        }
        if !assert_eq(sess.hist_count, 0, "hist_count should be 0") {
            return false;
        }
        if !assert_eq(sess.total_queries, 0, "total_queries should be 0") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 2: 히스토리 추가 및 조회
    func test_history_add_and_get() -> bool {
        println("Test 2: query_session_get_history");
        let sess = query_session.query_session_new(1002);

        // 히스토리가 비어있을 때 조회 (NOTFOUND)
        let (hist, err) = sess.query_session_get_history(0);
        if !assert_eq(err, query_session.QSESS_ERR_NOTFOUND, "should return NOTFOUND for empty history") {
            return false;
        }

        // 모의 히스토리 추가
        sess.history[0] = query_session.QueryHistory{
            sql:        "SELECT * WHERE id > 10",
            result_cnt: 5,
            exec_ok:    true,
            ts:         0,
        };
        sess.hist_count = 1;

        // 히스토리 조회
        let (hist2, err2) = sess.query_session_get_history(0);
        if !assert_eq(err2, query_session.QSESS_OK, "should return OK after adding history") {
            return false;
        }
        if !assert_str_eq(hist2.sql, "SELECT * WHERE id > 10", "sql should match") {
            return false;
        }
        if !assert_eq(hist2.result_cnt, 5, "result_cnt should be 5") {
            return false;
        }
        if !assert_bool(hist2.exec_ok, "exec_ok should be true") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 3: 전체 쿼리 수
    func test_get_total() -> bool {
        println("Test 3: query_session_get_total");
        let sess = query_session.query_session_new(1003);

        if !assert_eq(sess.query_session_get_total(), 0, "initial total_queries should be 0") {
            return false;
        }

        sess.total_queries = 5;
        if !assert_eq(sess.query_session_get_total(), 5, "total_queries should be 5 after update") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 4: 마지막 쿼리
    func test_last_query() -> bool {
        println("Test 4: query_session_last_query");
        let sess = query_session.query_session_new(1004);

        // 빈 세션에서 마지막 쿼리
        let last = sess.query_session_last_query();
        if !assert_str_eq(last, "", "empty session should return empty string") {
            return false;
        }

        // 히스토리 추가
        sess.history[0] = query_session.QueryHistory{
            sql:        "SELECT * WHERE id = 1",
            result_cnt: 1,
            exec_ok:    true,
            ts:         0,
        };
        sess.hist_count = 1;

        let last2 = sess.query_session_last_query();
        if !assert_str_eq(last2, "SELECT * WHERE id = 1", "should return last query") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 5: 히스토리 초기화
    func test_clear_history() -> bool {
        println("Test 5: query_session_clear_history");
        let sess = query_session.query_session_new(1005);

        // 히스토리 추가
        sess.history[0] = query_session.QueryHistory{
            sql:        "SELECT * WHERE id > 10",
            result_cnt: 5,
            exec_ok:    true,
            ts:         0,
        };
        sess.hist_count = 1;
        sess.total_queries = 1;

        // 초기화
        let err = sess.query_session_clear_history();
        if !assert_eq(err, query_session.QSESS_OK, "clear_history should return OK") {
            return false;
        }
        if !assert_eq(sess.hist_count, 0, "hist_count should be 0 after clear") {
            return false;
        }

        // total_queries는 유지되어야 함
        if !assert_eq(sess.total_queries, 1, "total_queries should remain unchanged") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 6: 통계 문자열
    func test_stats() -> bool {
        println("Test 6: query_session_stats");
        let sess = query_session.query_session_new(1006);
        sess.total_queries = 3;
        sess.hist_count = 2;

        let stats = sess.query_session_stats();
        if !assert_bool(len(stats) > 0, "stats should not be empty") {
            return false;
        }

        // 통계 문자열에 세션 ID, 전체 쿼리 수, 히스토리 수가 포함되어야 함
        println("Stats: " + stats);

        println("PASS");
        return true;
    }

    // Test 7: 범위 검증 (인덱스 오버플로우)
    func test_boundary_checks() -> bool {
        println("Test 7: boundary checks");
        let sess = query_session.query_session_new(1007);

        // 유효하지 않은 인덱스
        let (hist, err) = sess.query_session_get_history(10);
        if !assert_eq(err, query_session.QSESS_ERR_NOTFOUND, "should return NOTFOUND for invalid index") {
            return false;
        }

        // 음수 인덱스
        let (hist2, err2) = sess.query_session_get_history(-1);
        if !assert_eq(err2, query_session.QSESS_ERR_NOTFOUND, "should return NOTFOUND for negative index") {
            return false;
        }

        println("PASS");
        return true;
    }

    // Test 8: 에러 코드 값
    func test_error_codes() -> bool {
        println("Test 8: error code values");

        if !assert_eq(query_session.QSESS_OK, 0, "QSESS_OK should be 0") {
            return false;
        }
        if !assert_eq(query_session.QSESS_ERR_FULL, 180, "QSESS_ERR_FULL should be 180") {
            return false;
        }
        if !assert_eq(query_session.QSESS_ERR_NOTFOUND, 181, "QSESS_ERR_NOTFOUND should be 181") {
            return false;
        }

        println("PASS");
        return true;
    }

    // === 메인 테스트 실행 ===

    func run() -> i32 {
        println("========================================");
        println("QuerySession Module Tests");
        println("========================================");

        let pass_count = 0;
        let total_count = 8;

        if test_session_new() { pass_count = pass_count + 1; }
        if test_history_add_and_get() { pass_count = pass_count + 1; }
        if test_get_total() { pass_count = pass_count + 1; }
        if test_last_query() { pass_count = pass_count + 1; }
        if test_clear_history() { pass_count = pass_count + 1; }
        if test_stats() { pass_count = pass_count + 1; }
        if test_boundary_checks() { pass_count = pass_count + 1; }
        if test_error_codes() { pass_count = pass_count + 1; }

        println("========================================");
        println("Result: " + i32_to_str(pass_count) + "/" + i32_to_str(total_count) + " tests passed");
        println("========================================");

        if pass_count == total_count {
            return 0;
        }
        return 1;
    }
}

