        // 단순 반환: 0, pos+1
        return (i64(0), pos + 1);
    }

    // 5. qparse_op_from_str(op_str: string) -> i32
    // 문자열 → 연산자 타입 변환
    func qparse_op_from_str(op_str: string) -> i32 {
        if op_str == "=" || op_str == "==" {
            return OP_EQ;
        }
        if op_str == ">" {
            return OP_GT;
        }
        if op_str == "<" {
            return OP_LT;
        }
        if op_str == ">=" {
